21	/*!
22	 * \brief Check whether two regions have intersections.
23	 * \param region1 The first region.
24	 * \param region2 The second region.
25	 * \return Whether region1 and region2 have intersections.
26	 */
27	bool MayConflict(const Region &region1, const Region &region2) {
28	  ICHECK(region1.size() == region2.size());
29	  for (size_t i = 0; i < region1.size(); i++) {
30	    Range dim1 = region1[i];
31	    Range dim2 = region2[i];
32	    auto int_set1 = arith::IntSet::FromRange(dim1);
33	    auto int_set2 = arith::IntSet::FromRange(dim2);
34	    if (arith::Intersect({int_set1, int_set2}).IsNothing()) {
35	      return false;
36	    }
37	  }
38	  return true;
39	}
