41	class TmemLoadCollector : public StmtExprVisitor {
42	public:
43	  TmemLoadCollector() {}
44	
45	  Buffer result;
46	
47	private:
48	  void VisitExpr_(const BufferLoadNode *op) {
49	    Buffer buf = op->buffer;
50	    if (buf->data->type_annotation.as<PointerTypeNode>()->storage_scope ==
51	        "shared") {
52	      // We only care about shared.tmem buffers
53	      ICHECK(!result.defined())
54	          << "TmemLoadCollector: More than one shared buffer visited";
55	      result = buf;
56	    }
57	  }
