60	/*!
61	 * \brief Build the dependency chain between async operations and their
62	 *        corresponding buffers & synchronizations.
63	 *
64	 *        Example:
65	 *        If we encounter the following pattern:
66	 *
67	 *        tcgen5mma_gemm_ts(..., mbar, ...)
68	 *        mbarrier_wait_parity(mbar)
69	 *
70	 *        The builder will link the mbarrier to the buffers used in the
71	 * TCGEN5MMA
72	 */
73	class AsyncDependencyChainBuilder : public StmtExprVisitor {
74	public:
75	  AsyncDependencyChainBuilder(Map<Var, Buffer> buffer_data_to_buffer)
76	      : buffer_data_to_buffer_(buffer_data_to_buffer) {}
77	
78	  std::unordered_map<const BufferNode *, Array<BufferRegion>>
79	      mbar_to_buffer_reads_;
80	
81	  std::unordered_map<const BufferNode *, Array<BufferRegion>>
82	      mbar_to_buffer_writes_;
83	
84	private:
85	  Map<Var, Buffer> buffer_data_to_buffer_;
86	
87	  void VisitExpr_(const CallNode *op) final {
88	    auto args = op->args;
89	    if (op->op.same_as(builtin::call_extern())) {
90	      std::string func_name_with_template = args[0].as<StringImmNode>()->value;
91	      std::size_t le_pos = func_name_with_template.find_first_of('<');
92	      std::string func_name = le_pos == std::string::npos
93	                                  ? func_name_with_template
94	                                  : func_name_with_template.substr(0, le_pos);
95	      // TODO(lei): refactor to use identical ops.
96	      if (func_name == "tl::tcgen5mma_gemm_ts" ||
97	          func_name == "tl::tcgen5mma_gemm_ss") {
98	        // TCGEN5MMA
99	        auto get_buf_from_access_ptr_call =
100	            [&](const PrimExpr &expr) -> Buffer {
101	          auto call = expr.as<CallNode>();
102	          ICHECK(call);
103	          ICHECK(call->op.same_as(builtin::tvm_access_ptr()));
104	          auto var = call->args[1].as<VarNode>();
105	          ICHECK(var);
106	          auto it = buffer_data_to_buffer_.find(tvm::ffi::GetRef<Var>(var));
107	          ICHECK(it != buffer_data_to_buffer_.end());
108	          return (*it).second;
109	        };
110	        Buffer a_buf = get_buf_from_access_ptr_call(args[1]);
111	        Buffer b_buf = get_buf_from_access_ptr_call(args[2]);
112	        Buffer mbar_buf = get_buf_from_access_ptr_call(args[4]);
113	
114	        TmemLoadCollector tmem_collector;
115	        tmem_collector(args[3]);
116	        ICHECK(tmem_collector.result.defined())
117	            << "TmemLoadCollector: No tmem buffer load found in the TCGEN5MMA "
118	               "call";
119	        Buffer c_buf = tmem_collector.result;
120	
121	        PrimExpr clear_accum = args[5];
122	        mbar_to_buffer_reads_[mbar_buf.get()].push_back(
123	            BufferRegion::FullRegion(a_buf));
124	        mbar_to_buffer_reads_[mbar_buf.get()].push_back(
125	            BufferRegion::FullRegion(b_buf));
126	        mbar_to_buffer_writes_[mbar_buf.get()].push_back(
127	            BufferRegion::FullRegion(c_buf));
128	        auto analyzer = std::make_shared<arith::Analyzer>();
129	        if (!analyzer->CanProveEqual(clear_accum, Bool(true))) {
130	          mbar_to_buffer_reads_[mbar_buf.get()].push_back(
131	              BufferRegion::FullRegion(c_buf));
132	        }
133	      }
134	      // TODO (lei) Link wgmma to buffers and tl.wait_wgmma
135	    } else if (op->op.same_as(tir::builtin::if_then_else())) {
136	      const PrimExpr &then_expr = args[1];
137	      const PrimExpr &else_expr = args[2];
138	      this->VisitExpr(then_expr);
139	      this->VisitExpr(else_expr);
140	    } else {
141	      StmtExprVisitor::VisitExpr_(op);
142	    }
143	  }
144	};
