146	/*!
147	 * \brief Detect if a statement follows the global memory copy pattern:
148	 *        1. Contains exactly one buffer store operation
149	 *        2. Source buffer must be in global memory scope
150	 *        3. Destination buffer must be in local or shared memory scope
151	 */
152	class BufferRegionCollector : public StmtExprVisitor {
153	public:
154	  BufferRegionCollector(Map<Var, Buffer> buffer_data_to_buffer,
155	                        const AsyncDependencyChainBuilder &chain_builder)
156	      : buffer_data_to_buffer_(buffer_data_to_buffer),
157	        chain_builder_(chain_builder) {}
158	
159	  Array<BufferRegion> GetReads() const { return reads_; }
160	
161	  Array<BufferRegion> GetWrites() const { return writes_; }
162	
163	  bool GetGlobalCopyPattern() const { return is_global_copy_pattern_; }
164	
165	private:
166	  void VisitStmt_(const BufferStoreNode *op) final {
167	    Buffer store_buffer = op->buffer;
168	    Array<PrimExpr> indices = op->indices;
169	    // convert indices to region
170	    Array<Range> region;
171	    for (const auto &index : indices) {
172	      region.push_back(Range::FromMinExtent(index, 1));
173	    }
174	    auto store_region = BufferRegion(store_buffer, region);
175	    writes_.push_back(store_region);
176	
177	    is_global_read_ = false;
178	    this->VisitExpr(op->value);
179	    if (is_global_read_ && (store_buffer.scope() == "shared" ||
180	                            store_buffer.scope() == "shared.dyn")) {
181	      is_global_copy_pattern_ = true;
182	    }
183	    is_global_read_ = false;
184	  }
185	
186	  void VisitExpr_(const BufferLoadNode *op) final {
187	    auto load_buffer = op->buffer;
188	    Array<PrimExpr> indices = op->indices;
189	    // convert indices to region
190	    Array<Range> region;
191	    for (const auto &index : indices) {
192	      region.push_back(Range::FromMinExtent(index, 1));
193	    }
194	    auto load_region = BufferRegion(load_buffer, region);
195	    reads_.push_back(load_region);
196	
197	    if (op->buffer.scope() == "global" && !within_condition_expr_) {
198	      // skip condition expr of if_then_else node
199	      // shared[i] = T.if_then_else(global[i] < n, register_a[i], register_b[i])
200	      // is not a global read shared[i] = T.if_then_else(global[i] < n,
201	      // global_a[i], global_b[i]) is a global read
202	      is_global_read_ = true;
203	    }
204	  }
205	
206	  void VisitExpr_(const CallNode *op) final {
207	    auto args = op->args;
208	    if (op->op.same_as(builtin::address_of())) {
209	      BufferRegion buffer_region;
210	      if (const auto *load = op->args[0].as<BufferLoadNode>()) {
211	        buffer_region = BufferRegion::FullRegion(load->buffer);
212	      } else if (const auto *var_node = op->args[0].as<VarNode>()) {
213	        Var data_var = tvm::ffi::GetRef<Var>(var_node);
214	        auto it = buffer_data_to_buffer_.find(data_var);
215	        if (it != buffer_data_to_buffer_.end()) {
216	          buffer_region = BufferRegion::FullRegion((*it).second);
217	        }
218	      }
219	      if (buffer_region.defined()) {
220	        // because we only care about the buffer itself instead of indices
221	        reads_.push_back(buffer_region);
222	      }
223	    } else if (op->op.same_as(builtin::tvm_access_ptr())) {
224	      const VarNode *buffer_var = op->args[1].as<VarNode>();
225	      ICHECK(buffer_var);
226	      auto it = buffer_data_to_buffer_.find(tvm::ffi::GetRef<Var>(buffer_var));
227	      if (it != buffer_data_to_buffer_.end()) {
228	        const Buffer &buffer = (*it).second;
229	        const BufferRegion buffer_region = BufferRegion::FullRegion(buffer);
230	        // because we only care about the buffer itself instead of indices
231	        reads_.push_back(buffer_region);
232	      }
233	    } else if (op->op.same_as(builtin::if_then_else())) {
234	      within_condition_expr_ = true;
235	      this->VisitExpr(op->args[0]);
236	      within_condition_expr_ = false;
237	      for (auto i = 1; i < op->args.size(); i++) {
238	        this->VisitExpr(op->args[i]);
239	      }
240	    } else if (op->op.same_as(tl::mbarrier_wait_parity())) {
241	      ICHECK(args[0].as<BufferLoadNode>());
242	      Buffer mbar_buf = args[0].as<BufferLoadNode>()->buffer;
243	      auto buffer_reads =
244	          chain_builder_.mbar_to_buffer_reads_.find(mbar_buf.get());
245	      auto buffer_writes =
246	          chain_builder_.mbar_to_buffer_writes_.find(mbar_buf.get());
247	      if (buffer_reads != chain_builder_.mbar_to_buffer_reads_.end()) {
248	        reads_.insert(reads_.end(), buffer_reads->second.begin(),
249	                      buffer_reads->second.end());
250	      }
251	      if (buffer_writes != chain_builder_.mbar_to_buffer_writes_.end()) {
252	        writes_.insert(
253	            writes_.end(),
254	            chain_builder_.mbar_to_buffer_writes_.at(mbar_buf.get()).begin(),
255	            chain_builder_.mbar_to_buffer_writes_.at(mbar_buf.get()).end());
256	      }
257	    } else {
258	      StmtExprVisitor::VisitExpr_(op);
259	    }
260	  }
261	
262	  void VisitStmt_(const IfThenElseNode *op) final {
263	    within_condition_expr_ = true;
264	    this->VisitExpr(op->condition);
265	    within_condition_expr_ = false;
266	    this->VisitStmt(op->then_case);
267	    if (op->else_case.defined()) {
268	      within_condition_expr_ = true;
269	      this->VisitStmt(op->else_case.value());
270	      within_condition_expr_ = false;
271	    }
272	  }
273	
274	private:
275	  AsyncDependencyChainBuilder chain_builder_;
276	  Map<Var, Buffer> buffer_data_to_buffer_;
277	  Array<BufferRegion> reads_;
278	  Array<BufferRegion> writes_;
279	  bool is_global_read_ = false;
280	  bool under_buffer_store_ = false;
281	  bool is_global_copy_pattern_ = false;
282	  bool within_condition_expr_ = false;
283	};
