285	class PipelinePlanner : public StmtExprMutator {
286	public:
287	  static Stmt Substitute(const PrimFunc &f, bool use_async_copy = true) {
288	    PipelinePlanner substituter(use_async_copy);
289	    for (const auto &[_, buffer] : f->buffer_map) {
290	      substituter.buffer_data_to_buffer_.Set(buffer->data, buffer);
291	    }
292	    auto target = f->GetAttr<Target>(tvm::attr::kTarget);
293	    ICHECK(target.defined())
294	        << "Pipeline_Planning: Require the target attribute";
295	    substituter.target_ = target.value();
296	    return substituter.VisitStmt(f->body);
297	  }
298	
299	private:
300	  PipelinePlanner() = default;
301	  PipelinePlanner(bool use_async_copy) : use_async_copy_(use_async_copy) {}
302	
303	  /*! \brief Information about a pipeline stage
304	   *
305	   * \param reads Array of buffer regions read by this stage
306	   * \param writes Array of buffer regions written by this stage
307	   * \param original_stmt_index Original position of this stage in the pipeline
308	   * before reordering \param order Current position of this stage in the
309	   * pipeline after reordering (-1 if not yet assigned) \param stage Pipeline
310	   * stage number this operation belongs to (-1 if not yet assigned) \param
311	   * copy_stage Whether this stage is a memory copy operation \param
312	   * last_use_stmt_index Index of the last statement (in original order) that
313	   * uses the results of this stage (-1 if not yet determined). This field is
314	   * crucial for pipeline optimization:
315	   * - For copy stages: indicates the index of the last statement that reads
316	   * from the copied data, helping determine optimal placement of copy
317	   * operations
318	   * - Used to ensure copy operations are scheduled before their consumers
319	   * - A value of -1 means no subsequent statement uses this stage's output
320	   * - This information enables better pipeline scheduling by minimizing data
321	   *   dependencies and maximizing parallelism
322	   */
323	  struct PipelineStageInfo {
324	    Array<BufferRegion> reads, writes;
325	    int original_stmt_index{};
326	    int order = -1, stage = -1;
327	    bool copy_stage = false;
328	    bool producer_for_copy = false;
329	    int last_use_stmt_index =
330	        -1; // Initialized to -1, indicating no consumers found yet
331	
332	  public:
333	    bool is_first_stage() const { return copy_stage || producer_for_copy; }
334	    bool is_copy_stage() const { return copy_stage; }
335	    bool is_producer_for_copy() const { return producer_for_copy; }
336	    bool is_last_use_stmt_index_valid() const {
337	      return last_use_stmt_index != -1;
338	    }
339	  };
340	
341	  PipelineStageInfo
342	  MakePipelineStageInfo(Stmt stmt, int idx,
343	                        AsyncDependencyChainBuilder &chain_builder) {
344	    Block block(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{}, /*name_hint=*/"",
345	                /*body*/ std::move(stmt));
346	    Array<Array<BufferRegion>> access =
347	        GetBlockReadWriteRegion(block, buffer_data_to_buffer_);
348	    auto collector =
349	        BufferRegionCollector(buffer_data_to_buffer_, chain_builder);
350	    collector(block);
351	    PipelineStageInfo pinfo;
352	    pinfo.reads = std::move(collector.GetReads());
353	    pinfo.writes = std::move(collector.GetWrites());
354	    pinfo.original_stmt_index = idx;
355	    pinfo.copy_stage = collector.GetGlobalCopyPattern();
356	    return std::move(pinfo);
357	  }
358	
359	  Stmt VisitStmt_(const ForNode *loop) final {
360	    auto order_anno = loop->annotations.Get("tl_pipeline_order");
361	    auto stage_anno = loop->annotations.Get("tl_pipeline_stage");
362	    auto num_stages_anno = loop->annotations.Get("num_stages");
363	    if (order_anno && stage_anno) {
364	      // Check if order_anno or stage_anno contains -1, which means TMA+WS is
365	      // enabled
366	      bool ws_tma_enabled = false;
367	      auto order_array = Downcast<Array<Integer>>(order_anno.value());
368	      auto stage_array = Downcast<Array<Integer>>(stage_anno.value());
369	      for (const auto &val : order_array) {
370	        if (val->value == -1) {
371	          ws_tma_enabled = true;
372	          break;
373	        }
374	      }
375	      if (!ws_tma_enabled) {
376	        for (const auto &val : stage_array) {
377	          if (val->value == -1) {
378	            ws_tma_enabled = true;
379	            break;
380	          }
381	        }
382	      }
383	
384	      if (ws_tma_enabled) {
385	        return StmtExprMutator::VisitStmt_(loop);
386	      }
387	
388	      Map<String, Any> annotations;
389	      for (const auto &[key, value] : loop->annotations) {
390	        if (key != "tl_pipeline_order") {
391	          annotations.Set(key, value);
392	        }
393	      }
394	      annotations.Set(tir::attr::software_pipeline_order, order_anno.value());
395	
396	      for (const auto &[key, value] : loop->annotations) {
397	        if (key != "tl_pipeline_stage") {
398	          annotations.Set(key, value);
399	        }
400	      }
401	      annotations.Set(tir::attr::software_pipeline_stage, stage_anno.value());
402	      if (TargetHasAsyncCopy(target_) && use_async_copy_)
403	        annotations.Set(tir::attr::software_pipeline_async_stages,
404	                        Array<Integer>{0});
405	      auto for_node = tvm::ffi::GetRef<For>(loop);
406	      for_node.CopyOnWrite()->annotations = annotations;
407	      return for_node;
408	    }
409	
410	    if (!num_stages_anno)
411	      return StmtExprMutator::VisitStmt_(loop);
412	    int num_stages = num_stages_anno->as<IntImmNode>()->value;
413	    Stmt pipeline_body_root{nullptr};
414	    if (const auto *realize = loop->body.as<BlockRealizeNode>()) {
415	      const auto &block = realize->block;
416	      for (const auto &buffer : block->alloc_buffers) {
417	        ICHECK(buffer->IsInstance<BufferNode>());
418	        buffer_data_to_buffer_.Set(buffer->data, buffer);
419	      }
420	      pipeline_body_root = block->body;
421	    } else {
422	      pipeline_body_root = loop->body;
423	    }
424	    const SeqStmtNode *pipeline_body_seq = nullptr;
425	    {
426	      Stmt current = pipeline_body_root;
427	      while (true) {
428	        if (const auto *seq_stmt = current.as<SeqStmtNode>()) {
429	          pipeline_body_seq = seq_stmt;
430	          break;
431	        }
432	        if (const auto *if_then_else = current.as<IfThenElseNode>()) {
433	          ICHECK(!if_then_else->else_case.defined())
434	              << "Pipeline_Planning: Can't handle the body of the loop because "
435	                 "the IfThenElse node has an else branch";
436	          current = if_then_else->then_case;
437	          continue;
438	        }
439	        if (const auto *let_stmt = current.as<LetStmtNode>()) {
440	          current = let_stmt->body;
441	          continue;
442	        }
443	        LOG(FATAL) << "Pipeline_Planning: Can't handle the body of the loop "
444	                   << "because it is not a SeqStmt, IfThenElse without else, "
445	                   << "or LetStmt wrapping them, but got "
446	                   << current->GetTypeKey();
447	      }
448	    }
449	    ICHECK(pipeline_body_seq != nullptr);
450	
451	    CHECK(num_stages >= 1);
452	    CHECK(loop->kind == ForKind::kSerial);
453	
454	    AsyncDependencyChainBuilder chain_builder(buffer_data_to_buffer_);
455	    chain_builder(pipeline_body_root);
456	
457	    std::vector<PipelineStageInfo> pipeline_stage_infos;
458	    for (size_t i = 0; i < pipeline_body_seq->size(); i++) {
459	      auto pinfo =
460	          MakePipelineStageInfo(pipeline_body_seq->seq[i], i, chain_builder);
461	      pipeline_stage_infos.push_back(std::move(pinfo));
462	    }
463	
464	    // For every copy stage, mark all its dependency stages as producer_for_copy
465	    // Helper struct to manage copy stage dependency reads
466	    struct CopyStageDependencyReadsManager {
467	      std::vector<BufferRegion> regions;
468	
469	      // Add a region if not already present (by structural equality)
470	      void AddUnique(const BufferRegion &region) {
471	        for (const BufferRegion &copy_read : regions) {
472	          if (region->buffer.same_as(copy_read->buffer)) {
473	            return;
474	          }
475	        }
476	        regions.push_back(region);
477	      }
478	
479	      // Check if a region is present (by structural equality)
480	      bool Contains(const BufferRegion &region) const {
481	        for (const BufferRegion &copy_read : regions) {
482	          if (region->buffer.same_as(copy_read->buffer)) {
483	            return true;
484	          }
485	        }
486	        return false;
487	      }
488	
489	      size_t Size() const { return regions.size(); }
490	    };
491	
492	    CopyStageDependencyReadsManager copy_stage_dependency_reads_mgr;
493	
494	    // Step 1. Collect Copy reads
495	    for (const auto &pinfo : pipeline_stage_infos) {
496	      if (pinfo.is_copy_stage()) {
497	        for (const BufferRegion &read : pinfo.reads) {
498	          copy_stage_dependency_reads_mgr.AddUnique(read);
499	        }
500	      }
501	    }
502	
503	    // Step 2. find if pinfo write the copy reads, then update the
504	    // copy_stage_dependency_reads To prevent infinite loops, we set a maximum
505	    // number of iterations. In theory, the number of possible updates is
506	    // bounded by the number of pipeline stages, since each stage can only be
507	    // marked as producer_for_copy once, and each read can only be added once.
508	    // But for safety, we add a hard limit.
509	    const size_t max_iterations = (pipeline_stage_infos.size() * 4) + 16;
510	    size_t iter_count = 0;
511	
512	    for (auto &pinfo : pipeline_stage_infos) {
513	      if (!pinfo.is_copy_stage()) {
514	        continue;
515	      }
516	      auto original_copy_stmt_index = pinfo.original_stmt_index;
517	      bool updated = true;
518	      while (updated) {
519	        updated = false;
520	        for (auto &pinfo_inner : pipeline_stage_infos) {
521	          if (pinfo_inner.is_copy_stage()) {
522	            continue;
523	          }
524	          if (pinfo_inner.original_stmt_index >= original_copy_stmt_index) {
525	            break;
526	          }
527	
528	          bool should_prepare = false;
529	          for (const BufferRegion &write : pinfo_inner.writes) {
530	            if (copy_stage_dependency_reads_mgr.Contains(write)) {
531	              should_prepare = true;
532	              break;
533	            }
534	          }
535	          if (should_prepare && !pinfo_inner.is_producer_for_copy()) {
536	            pinfo_inner.producer_for_copy = true;
537	            updated = true;
538	          }
539	          if (should_prepare) {
540	            for (const BufferRegion &read : pinfo_inner.reads) {
541	              size_t before = copy_stage_dependency_reads_mgr.Size();
542	              copy_stage_dependency_reads_mgr.AddUnique(read);
543	              if (copy_stage_dependency_reads_mgr.Size() > before) {
544	                updated = true;
545	              }
546	            }
547	          }
548	        }
549	        iter_count++;
550	        if (iter_count > max_iterations) {
551	          LOG(FATAL)
552	              << "Pipeline planning: Exceeded maximum iterations ("
553	              << max_iterations << ") in copy stage dependency propagation. "
554	              << "This may indicate a cyclic or pathological dependency graph.";
555	        }
556	      }
557	    }
558	
559	    // Analysis use-def chain to determine last_use_stmt_index for copy
560	    // operations This step is critical for pipeline optimization as it
561	    // identifies the index of the last statement that consumes data produced by
562	    // copy stages, enabling optimal placement of copy operations in the
563	    // pipeline schedule.
564	    for (auto &pinfo : pipeline_stage_infos) {
565	      // Only analyze copy stages (memory copy operations)
566	      if (!pinfo.is_first_stage())
567	        continue;
568	
569	      // Check all subsequent statements to find the latest consumer
570	      for (int i = pinfo.original_stmt_index + 1;
571	           i < static_cast<int>(pipeline_body_seq->size()); i++) {
572	
573	        // Check if any read operation in statement 'i' uses data written by
574	        // this copy stage
575	        for (const BufferRegion &read : pipeline_stage_infos[i].reads) {
576	          // Look for overlapping buffer regions between this stage's writes and
577	          // stage 'i's reads
578	          if (std::find_if(pinfo.writes.begin(), pinfo.writes.end(),
579	                           [&](const BufferRegion &r) {
580	                             return r->buffer == read->buffer &&
581	                                    MayConflict(r->region, read->region);
582	                           }) != pinfo.writes.end()) {
583	            // Update last_use_stmt_index to the maximum (latest) statement
584	            // index that uses this data This ensures we capture the final
585	            // consumer of the copied data
586	            pinfo.last_use_stmt_index = std::max(pinfo.last_use_stmt_index, i);
587	          }
588	        }
589	        // Check for write-after-write conflicts (multiple stages writing to
590	        // same buffer region) This is important for pipeline correctness and
591	        // affects last_use_stmt_index analysis
592	        if (pinfo.is_copy_stage()) {
593	          for (const BufferRegion &write : pipeline_stage_infos[i].writes) {
594	            if (std::find_if(pinfo.writes.begin(), pinfo.writes.end(),
595	                             [&](const BufferRegion &r) {
596	                               return r->buffer == write->buffer &&
597	                                      MayConflict(r->region, write->region);
598	                             }) != pinfo.writes.end()) {
599	              LOG(FATAL) << "Pipeline planning error: Multiple writes to "
600	                            "overlapping buffer regions detected. "
601	                         << "Stage " << pinfo.original_stmt_index
602	                         << " and stage " << i
603	                         << " are both writing to buffer '"
604	                         << write->buffer->name
605	                         << "' with overlapping regions. This is not supported "
606	                            "in pipeline planning.";
607	            }
608	          }
609	        }
610	      }
611	    }
612	
613	    // Making stages and orders
614	    int order_idx = 0;
615	    // Stage 1. Create pipeline stages and assign order
616	    for (auto &pinfo : pipeline_stage_infos) {
617	      // Skip elements that must be in first stage:
618	      // 1. Copy stages (with active last_use_stmt_index) - these need special
619	      // handling
620	      //    because they have consumers that depend on their data
621	      // 2. All Producer stages for copy stages.
622	      if (pinfo.is_first_stage() && pinfo.is_last_use_stmt_index_valid()) {
623	        continue;
624	      }
625	
626	      // Main logic stage assignment:
627	      // - Increment order index
628	      // - Assign to new stage (current num_stages)
629	      pinfo.order = order_idx++;
630	      pinfo.stage = num_stages;
631	
632	      // Schedule copy stages that have this stage as their last consumer
633	      // This ensures copy operations are placed right before their final
634	      // consumer for optimal pipeline efficiency
635	      for (auto &pinfo_1 : pipeline_stage_infos) {
636	        if ((pinfo_1.is_first_stage() &&
637	             pinfo_1.last_use_stmt_index == pinfo.original_stmt_index)) {
638	          pinfo_1.order = order_idx++;
639	          pinfo_1.stage = 0; // Copy stages are typically assigned to stage 0
640	        }
641	      }
642	    }
643	
644	    ICHECK(size_t(order_idx) == pipeline_stage_infos.size())
645	        << "The number of stages should be equal to the number of pipeline "
646	           "stages. "
647	        << "Got " << order_idx << " stages and " << pipeline_stage_infos.size()
648	        << " pipeline stages.";
649	
650	    // Step 2. if all the copy is at the end of the order, we can move these
651	    // copy to the beginning of the order and shrink the stage offset by 1.
652	    int copy_stage_at_end = [&]() {
653	      int copy_stage_cnt = 0;
654	      int copy_order_min = pipeline_stage_infos.size();
655	      int non_copy_order_max = 0;
656	      for (auto &pinfo : pipeline_stage_infos) {
657	        if (pinfo.is_first_stage()) {
658	          copy_stage_cnt++;
659	          copy_order_min = std::min(copy_order_min, pinfo.order);
660	        } else {
661	          non_copy_order_max = std::max(non_copy_order_max, pinfo.order);
662	        }
663	      }
664	      if (copy_order_min > non_copy_order_max)
665	        return copy_stage_cnt;
666	      return -1;
667	    }();
668	    if (copy_stage_at_end > 0 && num_stages >= 2) {
669	      for (auto &pinfo : pipeline_stage_infos) { // move copy to the beginning
670	        pinfo.order =
671	            (pinfo.order + copy_stage_at_end) % pipeline_stage_infos.size();
672	        if (!pinfo.is_copy_stage() && !pinfo.is_producer_for_copy())
673	          pinfo.stage--;
674	      }
675	    }
676	
677	    // Finally, make the pipeline annotation
678	    Map<String, Any> annotations;
679	    for (const auto &[key, value] : loop->annotations) {
680	      if (key != "num_stages") {
681	        annotations.Set(key, value);
682	      }
683	    }
684	
685	    std::vector<Integer> orders, stages;
686	    orders.reserve(pipeline_stage_infos.size());
687	    stages.reserve(pipeline_stage_infos.size());
688	    for (auto &pinfo : pipeline_stage_infos) {
689	      orders.push_back(pinfo.order);
690	      stages.push_back(pinfo.stage);
691	    }
692	
693	    annotations.Set(tir::attr::software_pipeline_stage, Array<Integer>(stages));
694	    annotations.Set(tir::attr::software_pipeline_order, Array<Integer>(orders));
695	    if (TargetHasAsyncCopy(target_) && use_async_copy_)
696	      annotations.Set(tir::attr::software_pipeline_async_stages,
697	                      Array<Integer>{0});
698	
699	    return For(loop->loop_var, loop->min, loop->extent, loop->kind, loop->body,
700	               loop->thread_binding, annotations);
701	  }
702	
703	  Stmt VisitStmt_(const BlockNode *op) final {
704	    for (const auto &buffer : op->alloc_buffers) {
705	      buffer_data_to_buffer_.Set(buffer->data, buffer);
706	    }
707	    Block block = Downcast<Block>(StmtExprMutator::VisitStmt_(op));
708	    for (const auto &buffer : op->alloc_buffers) {
709	      buffer_data_to_buffer_.erase(buffer->data);
710	    }
711	    return std::move(block);
712	  }
713	
714	  Map<Var, Buffer> buffer_data_to_buffer_;
715	  Target target_;
716	  bool use_async_copy_{};
717	};
718	
719	tvm::transform::Pass PipelinePlanning() {
720	  using namespace tir::transform;
721	  auto pass_func = [=](PrimFunc f, const IRModule &m, PassContext ctx) {
722	    bool use_async_copy =
723	        ctx->GetConfig<Bool>("tir.use_async_copy", Bool(true)).value();
724	    PrimFuncNode *fptr = f.CopyOnWrite();
725	    fptr->body = PipelinePlanner::Substitute(f, use_async_copy);
726	    return f;
727	  };
728	  return CreatePrimFuncPass(pass_func, 0, "tl.PipelinePlanning", {});
729	}
730	
731	TVM_FFI_STATIC_INIT_BLOCK() {
732	  namespace refl = tvm::ffi::reflection;
733	  refl::GlobalDef().def("tl.transform.PipelinePlanning", PipelinePlanning);
734	}
735	
736	} // namespace tl
737	} // namespace tvm
