100	/*!
101	 * \brief Create a block and infer the access region with the given body.
102	 *
103	 * The result is a opaque block that doesn't contain any block iter vars. In
104	 * case the body is a block realize without predicate, it is unnecessary to
105	 * create a new block, the block of the block realize will be returned.
106	 *
107	 * \param body The body of the block.
108	 * \param buffer_data_to_buffer The map from buffer data to buffer.
109	 * \return The result block.
110	 */
111	Block MakeBlock(const Stmt &body,
112	                const Map<Var, Buffer> &buffer_data_to_buffer) {
113	  if (const BlockRealizeNode *block_realize = body.as<BlockRealizeNode>()) {
114	    if (is_one(block_realize->predicate)) {
115	      // no need to create a new block
116	      return block_realize->block;
117	    }
118	  }
119	  Block block(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{}, /*name_hint=*/"",
120	              /*body*/ body);
121	  Array<Array<BufferRegion>> access =
122	      GetBlockReadWriteRegion(block, buffer_data_to_buffer);
123	  BlockNode *n = block.CopyOnWrite();
124	  n->reads = access[0];
125	  n->writes = access[1];
126	  return block;
127	}
