129	/*! Structure that represents the provided annotation per block or loop. */
130	struct PipelineAnnotation {
131	  int stage;
132	  int order;
133	  bool async;
134	  // Index of the statement in the original loop body order (SeqStmt order)
135	  int original_idx = -1;
136	};
