146	/*!
147	 * \brief Rewriter for the body of the software pipeline. This pass inserts
148	 * `floormod` to indices of the remapped buffer to select the version
149	 * corresponding to the pipeline stage.
150	 */
151	class PipelineBodyRewriter : public StmtExprMutator {
152	public:
153	  /*!
154	   * \brief Constructor of PipelineBodyRewriter.
155	   * \param buffer_data_to_buffer The map from buffer data to buffer.
156	   * \param buffer_remap The map from original buffer to the buffer with updated
157	   * shape for multi-versioning in the software pipeline. \param pipeline_loop
158	   * The original loop to be software pipelined. \param access_all_versions
159	   * Whether all versions the buffers in the software pipeline are accessed.
160	   * This will be used to update block access region. In the prologue and
161	   * epilogue of a two-stage software pipeline, only one version of these
162	   * buffers are accessed.
163	   */
164	  PipelineBodyRewriter(const Map<Var, Buffer> &buffer_data_to_buffer,
165	                       const Map<Buffer, Buffer> &buffer_remap,
166	                       For pipeline_loop, bool access_all_versions)
167	      : buffer_data_to_buffer_(buffer_data_to_buffer),
168	        buffer_remap_(buffer_remap), pipeline_loop_(std::move(pipeline_loop)),
169	        access_all_versions_(access_all_versions) {}
170	
171	private:
172	  BufferRegion
173	  RewritePipelineBufferRegion(const BufferRegion &buffer_region) const {
174	    auto it = buffer_remap_.find(buffer_region->buffer);
175	    if (it != buffer_remap_.end()) {
176	      Region new_region = buffer_region->region;
177	      const Buffer &new_buffer = (*it).second;
178	      // For pipeline buffers, relax the access region of the first dimension to
179	      // full extent if access_all_versions == true
180	      Range accessed_version =
181	          access_all_versions_
182	              ? Range::FromMinExtent(0, new_buffer->shape[0])
183	              : Range::FromMinExtent(
184	                    floormod((pipeline_loop_->loop_var - pipeline_loop_->min),
185	                             new_buffer->shape[0]),
186	                    Integer(1));
187	      new_region.insert(new_region.begin(), accessed_version);
188	      return BufferRegion(new_buffer, new_region);
189	    }
190	    return buffer_region;
191	  }
192	
193	  PrimExpr RewriteBufferAccess(const Call &call,
194	                               const std::vector<int> &arg_indices) {
195	    auto product = [](const Array<PrimExpr> &input) {
196	      return foldl(
197	          [](PrimExpr a, PrimExpr b, Span span) {
198	            return mul(std::move(a), std::move(b), std::move(span));
199	          },
200	          make_const(DataType::Int(32), 1), input);
201	    };
202	    Array<PrimExpr> new_args = call->args;
203	    for (int i : arg_indices) {
204	      const Buffer &buffer =
205	          buffer_data_to_buffer_.at(Downcast<Var>(call->args[i]));
206	      auto it = buffer_remap_.find(buffer);
207	      if (it != buffer_remap_.end()) {
208	        const Buffer &new_buffer = (*it).second;
209	        const PrimExpr &old_index = call->args[i + 1];
210	        PrimExpr offset;
211	        if (new_buffer->strides.empty()) {
212	          offset = product(buffer->shape);
213	        } else {
214	          offset = new_buffer->strides[0];
215	        }
216	        PrimExpr new_index =
217	            old_index +
218	            floormod(pipeline_loop_->loop_var, new_buffer->shape[0]) * offset;
219	        new_args.Set(i + 1, new_index);
220	      }
221	    }
222	    return Call(call->dtype, call->op, new_args, call->annotations, call->span);
223	  }
224	
225	  Stmt VisitStmt_(const BlockNode *op) final {
226	    for (const Buffer &alloc_buffer : op->alloc_buffers) {
227	      buffer_data_to_buffer_.Set(alloc_buffer->data, alloc_buffer);
228	    }
229	    Block block = Downcast<Block>(StmtExprMutator::VisitStmt_(op));
230	    BlockNode *n = block.CopyOnWrite();
231	    n->reads.MutateByApply([this](const BufferRegion &buffer_region) {
232	      return RewritePipelineBufferRegion(buffer_region);
233	    });
234	    n->writes.MutateByApply([this](const BufferRegion &buffer_region) {
235	      return RewritePipelineBufferRegion(buffer_region);
236	    });
237	    for (const Buffer &alloc_buffer : op->alloc_buffers) {
238	      buffer_data_to_buffer_.erase(alloc_buffer->data);
239	    }
240	    return block;
241	  }
242	
243	  Stmt VisitStmt_(const BufferStoreNode *op) final {
244	    BufferStore store = Downcast<BufferStore>(StmtExprMutator::VisitStmt_(op));
245	    auto it = buffer_remap_.find(store->buffer);
246	    if (it == buffer_remap_.end()) {
247	      return store;
248	    }
249	    const Buffer &new_buffer = (*it).second;
250	    auto *n = store.CopyOnWrite();
251	    n->buffer = new_buffer;
252	    PrimExpr version = floormod(
253	        (pipeline_loop_->loop_var - pipeline_loop_->min), new_buffer->shape[0]);
254	    n->indices.insert(n->indices.begin(), version);
255	    return store;
256	  }
257	
258	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
259	    BufferLoad load = Downcast<BufferLoad>(StmtExprMutator::VisitExpr_(op));
260	    auto it = buffer_remap_.find(load->buffer);
261	    if (it == buffer_remap_.end()) {
262	      return load;
263	    }
264	    const Buffer &new_buffer = (*it).second;
265	    auto *n = load.CopyOnWrite();
266	    n->buffer = new_buffer;
267	    PrimExpr version = floormod(
268	        (pipeline_loop_->loop_var - pipeline_loop_->min), new_buffer->shape[0]);
269	    n->indices.insert(n->indices.begin(), version);
270	    return load;
271	  }
272	
273	  PrimExpr VisitExpr_(const CallNode *op) final {
274	    Call call = Downcast<Call>(StmtExprMutator::VisitExpr_(op));
275	    if (call->op.same_as(builtin::tvm_access_ptr())) {
276	      return RewriteBufferAccess(call, {1});
277	    }
278	    return call;
279	  }
280	
281	  Map<Var, Buffer> buffer_data_to_buffer_;
282	  Map<Buffer, Buffer> buffer_remap_;
283	  For pipeline_loop_;
284	  bool access_all_versions_;
285	};
