287	/*!
288	 * \brief Rewriter for the software pipeline that rewrite a loop into a
289	 * pipelined one.
290	 */
291	class PipelineRewriter : public StmtExprMutator {
292	public:
293	  /*!
294	   * \brief Constructor of PipelineRewriter.
295	   * \param buffer_data_to_buffer The map from buffer data to buffer.
296	   * \param pipeline_allocs All buffers that need multi-versioning in the
297	   * pipeline. This includes buffers allocated in the pipeline block and
298	   * buffers allocated in outer blocks that are used in the pipeline.
299	   * \param local_allocs Buffers that are allocated in the pipeline block
300	   * itself. These buffers will be re-allocated in the rewritten block.
301	   * Buffers in pipeline_allocs but not in local_allocs are allocated in outer
302	   * blocks and should not be re-allocated.
303	   * \param pipeline_loop The original loop to be software pipelined.
304	   * \param pipeline_info The pipeline annotation information.
305	   * \param loop_var_let_wrappers Let wrappers that depend on the loop var.
306	   */
307	  PipelineRewriter(Map<Var, Buffer> buffer_data_to_buffer,
308	                   const Array<Buffer> &pipeline_allocs,
309	                   const Array<Buffer> &local_allocs, const For &pipeline_loop,
310	                   const PipelineInfo &pipeline_info,
311	                   const std::vector<LetWrapper> &loop_var_let_wrappers)
312	      : buffer_data_to_buffer_(std::move(buffer_data_to_buffer)),
313	        pipeline_allocs_(pipeline_allocs), local_allocs_(local_allocs),
314	        pipeline_loop_(pipeline_loop), pipeline_info_(pipeline_info),
315	        loop_var_let_wrappers_(loop_var_let_wrappers) {}
316	
317	  Stmt BuildPipeline() {
318	    // Step 1: Analyze accesses to the buffers in the pipeline and compute the
319	    // number of versions need to maintain for each buffer.
320	    std::unordered_map<Buffer, BufferAccessInfo, ObjectPtrHash, ObjectPtrEqual>
321	        infos = GetBufferAccessInfo();
322	    for (const Buffer &buffer : pipeline_allocs_) {
323	      auto it = infos.find(buffer);
324	      if (it == infos.end()) {
325	        // Buffer is not accessed in the pipeline blocks, skip it
326	        continue;
327	      }
328	      int num_versions = ComputeBufferVersions(buffer, it->second);
329	      if (num_versions > 1) {
330	        buffer_remap_.Set(buffer, RewriteAllocBuffer(buffer, num_versions));
331	      }
332	    }
333	    ordered_stmts_.resize(pipeline_info_.size());
334	    for (const auto &[block, anno] : pipeline_info_) {
335	      ordered_stmts_.Set(anno.order, block);
336	    }
337	
338	    for (const Block &block : ordered_stmts_) {
339	      int stage = pipeline_info_[block].stage;
340	      if (pipeline_info_[block].async) {
341	        auto &state = async_states[stage];
342	        state.producer_head = pipeline_loop_->min - 1;
343	        for (auto write_region : block->writes) {
344	          auto buffer = write_region->buffer;
345	          state.dst_buffers.insert(buffer.get());
346	          if (buffer_remap_.count(buffer))
347	            state.dst_buffers.insert(buffer_remap_[buffer].get());
348	        }
349	      }
350	    }
351	    std::unordered_set<int> consumed;
352	    for (const Block &block : ordered_stmts_) {
353	      int stage = pipeline_info_[block].stage;
354	      if (pipeline_info_[block].async) {
355	        auto &state = async_states[stage];
356	        if (state.commit_groups.empty() || consumed.count(stage)) {
357	          state.commit_groups.push_back({});
358	        }
359	        state.commit_groups.back().push_back(pipeline_info_[block].order);
360	        consumed.erase(stage);
361	        for (auto write_region : block->writes) {
362	          auto buffer = buffer_remap_.count(write_region->buffer)
363	                            ? buffer_remap_[write_region->buffer]
364	                            : write_region->buffer;
365	          state.buffer_to_commit_group_[buffer.get()] =
366	              state.commit_groups.size() - 1;
367	        }
368	      }
369	
370	      for (auto read_region : block->reads) {
371	        for (const auto &[producer_stage_id, producer_state] : async_states) {
372	          if (producer_stage_id <= stage &&
373	              producer_state.writes(read_region->buffer)) {
374	            consumed.insert(producer_stage_id);
375	          }
376	        }
377	      }
378	    }
379	
380	    // Step 2: Emit the pipeline prologue, body and epilogue.
381	    Stmt prologue =
382	        EmitImpl(pipeline_loop_->min, pipeline_loop_->min + max_stage_, true,
383	                 true, false);
384	    Stmt body = EmitImpl(pipeline_loop_->min + max_stage_,
385	                         pipeline_loop_->min + pipeline_loop_->extent, false,
386	                         false, false);
387	
388	    Stmt epilogue =
389	        EmitImpl(pipeline_loop_->min + pipeline_loop_->extent,
390	                 pipeline_loop_->min + pipeline_loop_->extent + max_stage_,
391	                 true, true, true);
392	    SeqStmt stmt = SeqStmt({prologue, body, epilogue});
393	
394	    // Step 3: Make a new block that contains new buffer allocations after
395	    // pipeline rewriting.
396	    // Only include buffers that are locally allocated in the pipeline block.
397	    // Buffers from outer blocks will be handled separately.
398	    Array<Buffer> alloc_buffers;
399	    std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual> local_allocs_set(
400	        local_allocs_.begin(), local_allocs_.end());
401	    for (const auto &alloc : local_allocs_) {
402	      alloc_buffers.push_back(buffer_remap_.Get(alloc).value_or(alloc));
403	      buffer_data_to_buffer_.erase(alloc->data);
404	    }
405	    Block block = MakeBlock(stmt, buffer_data_to_buffer_);
406	    block.CopyOnWrite()->alloc_buffers = std::move(alloc_buffers);
407	    return BlockRealize({}, Bool(true), block);
408	  }
