410	  /*!
411	   * \brief Get the buffer remapping created during pipeline rewriting.
412	   * This is used to update alloc_buffers in outer blocks.
413	   */
414	  const Map<Buffer, Buffer> &GetBufferRemap() const { return buffer_remap_; }
