416	private:
417	  /*!
418	   * \brief Analyze accesses to the buffers in the software pipeline.
419	   *
420	   * This method check the 'define' and 'use' stage of the buffers in the
421	   * software pipeline, which can be used to compute the number of versions
422	   * needed to maintain after rewriting.
423	   */
424	  std::unordered_map<Buffer, BufferAccessInfo, ObjectPtrHash, ObjectPtrEqual>
425	  GetBufferAccessInfo() {
426	    std::unordered_map<Buffer, BufferAccessInfo, ObjectPtrHash, ObjectPtrEqual>
427	        infos;
428	    for (const auto &pair : pipeline_info_) {
429	      const Block &block = pair.first;
430	      int stage = pair.second.stage;
431	      max_stage_ = std::max(max_stage_, stage);
432	
433	      for (const BufferRegion &write : block->writes) {
434	        if (!infos.count(write->buffer)) {
435	          infos.emplace(write->buffer, BufferAccessInfo{});
436	        }
437	        auto &info = infos.at(write->buffer);
438	        if (info.def == -1) {
439	          info.def = stage;
440	        } else {
441	          info.def = std::min(info.def, stage);
442	        }
443	      }
444	
445	      for (const BufferRegion &read : block->reads) {
446	        if (!infos.count(read->buffer)) {
447	          infos.emplace(read->buffer, BufferAccessInfo{});
448	        }
449	        auto &info = infos.at(read->buffer);
450	        info.use = std::max(info.use, stage);
451	      }
452	    }
453	    return infos;
454	  }
455	
456	  /*!
457	   * \brief Check whether two regions have intersections.
458	   * \param region1 The first region.
459	   * \param region2 The second region.
460	   * \return Whether region1 and region2 have intersections.
461	   */
462	  bool MayConflict(const Region &region1, const Region &region2) {
463	    ICHECK(region1.size() == region2.size());
464	    for (size_t i = 0; i < region1.size(); i++) {
465	      Range dim1 = region1[i];
466	      Range dim2 = region2[i];
467	      auto int_set1 = arith::IntSet::FromRange(dim1);
468	      auto int_set2 = arith::IntSet::FromRange(dim2);
469	      if (arith::Intersect({int_set1, int_set2}).IsNothing()) {
470	        return false;
471	      }
472	    }
473	    return true;
474	  }
475	
476	  /*!
477	   * \brief Compute the number of versions need to maintain for buffer accessed
478	   * in the software pipeline.
479	   *
480	   * This method applies liveness analysis to the target buffer to compute the
481	   * number of versions need to maintain during the software pipeline.
482	   * Annotation `attr::double_buffer_scope` is handled here which provides a way
483	   * to override the result of the analysis. Additional double buffering in the
484	   * software pipeline can be useful to eliminate synchronizations in GPU
485	   * devices.
486	   *
487	   * \param buffer The target buffer
488	   * \param buffer_info The access information of the target buffer.
489	   * \return The number of versions required for the target buffer.
490	   */
491	  int ComputeBufferVersions(const Buffer &buffer,
492	                            const BufferAccessInfo &buffer_info) {
493	    if (buffer_info.def == -1) {
494	      // Keep the original number of versions as buffers defined outside the
495	      // software pipeline should not be mutated.
496	      return 1;
497	    }
498	
499	    // `use - def + 1` is a upper bound of the needed versions
500	    // We optimize a few case where the number of versions can be smaller than
501	    // the upper bound
502	    int num_versions = buffer_info.use - buffer_info.def + 1;
503	    if (num_versions >= 2) {
504	      // A special case when `use - def + 1 == 2`. Double buffering is only
505	      // needed in this case when these exists a reader block_i and a writer
506	      // block_j such that order(block_i) < order(block_j) and stage(block_i) <
507	      // stage(block_j) and the access regions of block_i and block_j overlap.
508	      bool need_multi_version = false;
509	      for (const auto &pair1 : pipeline_info_) {
510	        const Block &writer_block = pair1.first;
511	        const auto &writer_info = pair1.second;
512	
513	        auto it1 = std::find_if(writer_block->writes.begin(),
514	                                writer_block->writes.end(),
515	                                [&](const BufferRegion &buffer_region) {
516	                                  return buffer_region->buffer.same_as(buffer);
517	                                });
518	        if (it1 == writer_block->writes.end()) {
519	          continue;
520	        }
521	
522	        for (const auto &pair2 : pipeline_info_) {
523	          const Block &reader_block = pair2.first;
524	          const auto &reader_info = pair2.second;
525	          auto it2 = std::find_if(
526	              reader_block->reads.begin(), reader_block->reads.end(),
527	              [&](const BufferRegion &buffer_region) {
528	                return buffer_region->buffer.same_as(buffer);
529	              });
530	          if (it2 == reader_block->reads.end()) {
531	            continue;
532	          }
533	          if (writer_info.order < reader_info.order &&
534	              writer_info.stage < reader_info.stage &&
535	              MayConflict((*it1)->region, (*it2)->region)) {
536	            need_multi_version = true;
537	            break;
538	          }
539	        }
540	      }
541	      if (!need_multi_version) {
542	        num_versions--;
543	      }
544	    }
545	    return num_versions;
546	  }
547	
548	  /*!
549	   * \brief Rewrite buffer allocation to keep multiple versions of original
550	   * buffer for pipelined accesses. \param buffer The buffer to be resized.
551	   * \param num_versions The number of versions to keep.
552	   * \return The resized buffer.
553	   */
554	  Buffer RewriteAllocBuffer(const Buffer &buffer, int num_versions) {
555	    ObjectPtr<BufferNode> new_buffer =
556	        tvm::ffi::make_object<BufferNode>(*(buffer.get()));
557	    new_buffer->shape.insert(new_buffer->shape.begin(), PrimExpr(num_versions));
558	    if (!new_buffer->strides.empty()) {
559	      ICHECK(new_buffer->strides.size() + 1 == new_buffer->shape.size());
560	      PrimExpr stride_0 = new_buffer->strides[0] * new_buffer->shape[1];
561	      new_buffer->strides.insert(new_buffer->strides.begin(), stride_0);
562	    }
563	    return Buffer(new_buffer);
564	  }
565	
566	  // Per-stage states that need to be tracked across pipeline prologue, body,
567	  // and epilogue.
568	  struct AsyncStateGlobal {
569	    // Buffers that this stage asynchronously writes.
570	    std::unordered_set<const BufferNode *> dst_buffers;
571	    // An imaginary index that the latest async operation associated with this
572	    // stage has written into. Only valid if all associated predicates are true,
573	    // so that we can count the number of async invocations exactly. When it is
574	    // valid, it is the "sum of extents of loops that have been executed" - 1,
575	    // e.g. for epilogue it is prologue extent + body extent - 1. This is only
576	    // needed to compute wait count for epilogue without async producers.
577	    PrimExpr producer_head;
578	    std::vector<std::vector<int>> commit_groups;
579	    std::unordered_map<const BufferNode *, int> buffer_to_commit_group_;
580	    bool writes(const Buffer &buf) const {
581	      return dst_buffers.count(buf.get()) > 0;
582	    }
583	  };
584	
585	  // Per-stage states that are local to each of pipeline prologue, body, and
586	  // epilogue.
587	  struct AsyncStateLocal {
588	    struct PendingWait {
589	      // The index into a list of blocks, where async_wait_queue should be
590	      // attached at the beginning.
591	      int insert_before;
592	      // in_flight_count would be a more precise name, but the implementation
593	      // uses wait_count for brevity.
594	      PrimExpr wait_count{nullptr};
595	
596	      bool valid() const { return wait_count.defined(); }
597	    };
598	
599	    std::vector<PendingWait> pending_waits;
600	
601	    // A symbolic expression representing the index the latest async operation
602	    // associated with this stage has written into, at the "current" iteration.
603	    Optional<PrimExpr> producer_head;
604	    // the commit block's predicate
605	    PrimExpr commit_predicate{nullptr};
606	  };
607	
608	  /*! Structure holding intermediate information for pipeline loop rewriting. */
609	  struct RewrittenBlockInfo {
610	    int stage;
611	    int order;
612	    PrimExpr start;
613	    PrimExpr end;
614	    PrimExpr predicate;
615	    Block block;
616	    PrimExpr access_index;
617	    bool is_async;
618	  };
619	
620	  void PopulateWaitCounts(const std::vector<RewrittenBlockInfo> &new_blocks,
621	                          std::map<int, AsyncStateLocal> *async_states_local,
622	                          bool is_epilogue = false) {
623	    // Precompute which orders are present in this emit, and their access_index
624	    std::unordered_map<int, PrimExpr> order_to_access_index;
625	    std::unordered_set<int> present_orders;
626	    for (const auto &nb : new_blocks) {
627	      order_to_access_index[nb.order] = nb.access_index;
628	      present_orders.insert(nb.order);
629	    }
630	    for (size_t i = 0; i < new_blocks.size(); ++i) {
631	      // 1. Find the unique async producer stage
632	      int producer_stage_idx = -1;
633	      for (const auto &read_region : new_blocks[i].block->reads) {
634	        for (const auto &[stage, state] : async_states) {
635	          if (stage <= new_blocks[i].stage &&
636	              state.writes(read_region->buffer)) {
637	            // Currently only a single async stage dependency is supported
638	            ICHECK(producer_stage_idx == -1 || producer_stage_idx == stage)
639	                << "A dependency on multiple async stages is not supported";
640	            producer_stage_idx = stage;
641	          }
642	        }
643	      }
644	      if (producer_stage_idx == -1) {
645	        // This block does not depend on any async producer
646	        continue;
647	      }
648	      const auto &state = async_states[producer_stage_idx];
649	
650	      auto &dep_local_state = (*async_states_local)[producer_stage_idx];
651	
652	      // 2. Use buffer_to_commit_group_ to find all actually dependent commit
653	      // groups
654	      std::unordered_set<int> dependent_groups;
655	      for (const auto &read_region : new_blocks[i].block->reads) {
656	        auto it = state.buffer_to_commit_group_.find(read_region->buffer.get());
657	        if (it != state.buffer_to_commit_group_.end()) {
658	          dependent_groups.insert(it->second);
659	        }
660	      }
661	
662	      // If there is no dependent commit group, no wait needs to be inserted
663	      if (dependent_groups.empty()) {
664	        continue;
665	      }
666	
667	      // 3. Compute wait = max_g max(0, t_consumer - committed_before[g])
668	      PrimExpr t_consumer = new_blocks[i].access_index;
669	      PrimExpr wait_expr = make_zero(t_consumer.dtype());
670	
671	      PrimExpr current_head = dep_local_state.producer_head.defined()
672	                                  ? dep_local_state.producer_head.value()
673	                                  : state.producer_head;
674	      int consumer_order = new_blocks[i].order;
675	
676	      for (int g : dependent_groups) {
677	        const auto &group = state.commit_groups[g];
678	        if (group.empty())
679	          continue;
680	        int commit_order = group.back();
681	        bool commit_present = present_orders.count(commit_order) > 0;
682	
683	        PrimExpr committed_before;
684	        if (commit_present && commit_order <= consumer_order) {
685	          // Commit point is in this iteration and earlier than the current
686	          // consumer; this iteration's head is visible
687	          auto commit_predicate = dep_local_state.commit_predicate;
688	          if (analyzer_.CanProve(!commit_predicate,
689	                                 arith::ProofStrength::kSymbolicBound)) {
690	            // it means the commit block is not executed in this iteration
691	            committed_before = new_blocks[i].start - 1;
692	          } else if (is_epilogue) {
693	            committed_before = new_blocks[i].start - 1;
694	          } else {
695	            committed_before = order_to_access_index.at(commit_order);
696	          }
697	        } else {
698	          // Commit point is later than the current consumer or not in this
699	          // iteration; only the previous iteration's head is visible
700	          if (dep_local_state.producer_head.defined()) {
701	            auto commit_predicate = dep_local_state.commit_predicate;
702	            if (analyzer_.CanProve(!commit_predicate,
703	                                   arith::ProofStrength::kSymbolicBound)) {
704	              committed_before = new_blocks[i].start - 1;
705	            } else if (is_epilogue) {
706	              committed_before = new_blocks[i].start - 1;
707	            } else {
708	              committed_before = current_head - 1;
709	            }
710	          }
711	        }
712	
713	        wait_expr = analyzer_.Simplify(committed_before - t_consumer);
714	      }
715	
716	      wait_expr = analyzer_.Simplify(wait_expr);
717	      dep_local_state.pending_waits.push_back({static_cast<int>(i), wait_expr});
718	    }
719	  }
720	
721	  // Given pipelined blocks and async-related information, generate final loop
722	  // statements with async scopes (if any).
723	  Array<Stmt> CompletePipelineLoopStatements(
724	      const std::vector<RewrittenBlockInfo> &blocks,
725	      const std::map<int, AsyncStateLocal> &async_states_local) const {
726	    std::vector<RewrittenBlockInfo> new_blocks = blocks;
727	    for (const auto &[stage_id, state] : async_states_local) {
728	      for (const auto &pw : state.pending_waits) {
729	        auto &block = new_blocks[pw.insert_before].block;
730	        BlockNode *n = block.CopyOnWrite();
731	        auto zero = make_zero(DataType::Int(32));
732	        n->body = AttrStmt(zero, tir::attr::async_wait_queue_scope, stage_id,
733	                           AttrStmt(zero, tir::attr::async_wait_inflight_count,
734	                                    pw.wait_count, n->body));
735	      }
736	    }
737	
738	    // mark the last async stmt as commit
739	    std::unordered_set<int> commit_group_indices;
740	    for (const auto &[stage_id, state] : async_states) {
741	      for (size_t i = 0; i < state.commit_groups.size(); ++i) {
742	        commit_group_indices.insert(state.commit_groups[i].back());
743	      }
744	    }
745	
746	    Array<Stmt> stmts;
747	
748	    for (size_t i = 0; i < new_blocks.size(); i++) {
749	      Block block = new_blocks[i].block;
750	      if (commit_group_indices.count(new_blocks[i].order)) {
751	        auto commit_queue_scope = AttrStmt(make_zero(DataType::Int(32)),
752	                                           tir::attr::async_commit_queue_scope,
753	                                           new_blocks[i].stage, block->body);
754	        block = MakeBlock(commit_queue_scope, buffer_data_to_buffer_);
755	      }
756	      stmts.push_back(BlockRealize({}, new_blocks[i].predicate, block));
757	    }
758	
759	    return stmts;
760	  }
761	
762	  /*!
763	   * \brief Emit the pipeline loop in the given range.
764	   * \param start The start of the range
765	   * \param end The end of the range
766	   * \param unroll_loop Whether the loop should be unrolled.
767	   * \return The result loop.
768	   */
769	  Stmt EmitImpl(const PrimExpr &start, const PrimExpr &end, bool unroll_loop,
770	                bool need_bound_check, bool is_epilogue = false) {
771	    PrimExpr new_loop_var;
772	    PrimExpr extent = end - start;
773	    auto make_nop = []() {
774	      return BlockRealize({}, Bool(true), MakeBlock(Evaluate(0), {}));
775	    };
776	
777	    bool is_unit_loop = analyzer_.CanProveEqual(extent, 1);
778	    if (is_unit_loop) {
779	      new_loop_var = start; // use constants as the loop var for unit loops
780	    } else {
781	      new_loop_var = pipeline_loop_->loop_var.copy_with_suffix("");
782	      // Bind the iteration domain [start, end) to strengthen analyzer facts.
783	      analyzer_.Bind(Downcast<Var>(new_loop_var),
784	                     Range::FromMinExtent(start, end - start));
785	    }
786	    // Keep the bound constraints active for all analysis below.
787	    // Only meaningful when the loop var is symbolic (non-unit loop).
788	    std::unique_ptr<With<arith::ConstraintContext>> ctx_lb_guard;
789	    std::unique_ptr<With<arith::ConstraintContext>> ctx_ub_guard;
790	    if (!is_unit_loop) {
791	      Var loop_iter = Downcast<Var>(new_loop_var);
792	      ctx_lb_guard.reset(
793	          new With<arith::ConstraintContext>(&analyzer_, loop_iter >= start));
794	      ctx_ub_guard.reset(
795	          new With<arith::ConstraintContext>(&analyzer_, loop_iter < end));
796	    }
797	
798	    std::vector<RewrittenBlockInfo> new_blocks;
799	
800	    // Async related
801	    std::map<int, AsyncStateLocal> async_states_local;
802	
803	    for (const Block &block : ordered_stmts_) {
804	      int stage = pipeline_info_.at(block).stage;
805	      int order = pipeline_info_.at(block).order;
806	
807	      PrimExpr inbound = Bool(true);
808	      PrimExpr skewed_loop_var = new_loop_var - stage;
809	      if (need_bound_check)
810	        inbound = And(
811	            pipeline_loop_->min <= skewed_loop_var,
812	            (skewed_loop_var < pipeline_loop_->min + pipeline_loop_->extent));
813	
814	      Block new_block = Downcast<Block>(
815	          PipelineBodyRewriter(buffer_data_to_buffer_, buffer_remap_,
816	                               pipeline_loop_, max_stage_ != 1)(block));
817	
818	      PrimExpr delta = start - pipeline_loop_->min;
819	      // This variable corresponds to
820	      // - "producer_head" if this stage is an async producer
821	      // - "consumer_head" if this stage reads from asynchronously written
822	      // buffers.
823	      PrimExpr normalized_access_index =
824	          is_unit_loop ? skewed_loop_var : skewed_loop_var + delta;
825	
826	      normalized_access_index = analyzer_.Simplify(normalized_access_index);
827	
828	      // Adjust the block predicate and the body according to the final loop
829	      // bound
830	      //  [pipeline_loop_->min, extent).
831	      if (!is_unit_loop) {
832	        Var loop_iter = Downcast<Var>(new_loop_var);
833	        inbound = Substitute(inbound, {{loop_iter, loop_iter + delta}});
834	      }
835	      new_block = Downcast<Block>(Substitute(
836	          new_block, {{pipeline_loop_->loop_var, normalized_access_index}}));
837	
838	      // If there were Let-wrappers outside the original pipeline body that
839	      // depended on the pipeline loop var, push them into each rewritten
840	      // block with the correct per-block substitution.
841	      if (!loop_var_let_wrappers_.empty()) {
842	        BlockNode *n = new_block.CopyOnWrite();
843	        Stmt inner = n->body;
844	        for (const auto &lw : loop_var_let_wrappers_) {
845	          PrimExpr substituted = Substitute(
846	              lw.value, {{pipeline_loop_->loop_var, normalized_access_index}});
847	          inner = LetStmt(lw.var, substituted, inner);
848	        }
849	        n->body = inner;
850	      }
851	
852	      if (pipeline_info_[block].async) {
853	        auto &local_state = async_states_local[stage];
854	        local_state.producer_head = normalized_access_index;
855	        local_state.commit_predicate = inbound;
856	        BlockNode *n = new_block.CopyOnWrite();
857	        n->body = AttrStmt(make_zero(DataType::Int(32)), tir::attr::async_scope,
858	                           1, n->body);
859	      }
860	
861	      new_blocks.push_back({stage, order, start, end, inbound, new_block,
862	                            normalized_access_index,
863	                            pipeline_info_[block].async});
864	    }
865	
866	    PopulateWaitCounts(new_blocks, &async_states_local, is_epilogue);
867	
868	    auto stmts = CompletePipelineLoopStatements(new_blocks, async_states_local);
869	
870	    Stmt new_loop{nullptr};
871	
872	    if (stmts.empty()) {
873	      return make_nop();
874	    }
875	
876	    if (stmts.size() == 1) {
877	      new_loop = stmts[0];
878	    } else {
879	      new_loop = SeqStmt(stmts);
880	    }
881	
882	    if (!is_unit_loop) {
883	      Map<String, Any> preserved_annotations;
884	      for (const auto &kv : pipeline_loop_->annotations) {
885	        const String &key = kv.first;
886	        if (kv.first != tir::attr::software_pipeline_stage &&
887	            kv.first != tir::attr::software_pipeline_order &&
888	            kv.first != tir::attr::software_pipeline_async_stages) {
889	          preserved_annotations.Set(key, kv.second);
890	        }
891	      }
892	      new_loop = For(Downcast<Var>(new_loop_var), pipeline_loop_->min, extent,
893	                     unroll_loop ? ForKind::kUnrolled : pipeline_loop_->kind,
894	                     std::move(new_loop), std::nullopt, preserved_annotations);
895	    }
896	    // Update producer heads in the global async states.
897	    for (const auto &[stage_id, state] : async_states_local) {
898	      async_states[stage_id].producer_head += extent;
899	    }
900	
901	    return BlockRealize({}, Bool(true),
902	                        MakeBlock(new_loop, buffer_data_to_buffer_));
903	  }
904	
905	  arith::Analyzer analyzer_;
906	  Map<Var, Buffer> buffer_data_to_buffer_;
907	  Array<Buffer> pipeline_allocs_;
908	  Array<Buffer> local_allocs_;
909	  For pipeline_loop_;
910	  PipelineInfo pipeline_info_;
911	  int max_stage_ = -1;
912	  Map<Buffer, Buffer> buffer_remap_;
913	  Array<Block> ordered_stmts_;
914	  std::map<int, AsyncStateGlobal> async_states;
915	  std::vector<LetWrapper> loop_var_let_wrappers_;
916	};
917	
918	/*!
919	 * \brief Build the dependency graph among a array of blocks.
920	 * \param[in] blocks The array of blocks.
921	 * \param[out] dep_src2dst Optional, a map to store dependency edges from the
922	 * source to the destination. \param[out] dep_dst2src Optional, a map to store
923	 * dependency edges from the destination to the source.
924	 */
925	void BuildDependencyGraph(const Array<Block> &blocks,
926	                          std::unordered_map<Block, Array<Block>, ObjectPtrHash,
927	                                             ObjectPtrEqual> *dep_src2dst,
928	                          std::unordered_map<Block, Array<Block>, ObjectPtrHash,
929	                                             ObjectPtrEqual> *dep_dst2src) {
930	  std::unordered_map<Var, Array<Block>, ObjectPtrHash, ObjectPtrEqual>
931	      buffer_writers;
932	
933	  for (const Block &block : blocks) {
934	    for (const BufferRegion &read : block->reads) {
935	      auto it = buffer_writers.find(read->buffer->data);
936	      if (it != buffer_writers.end()) {
937	        for (const Block &writer : it->second) {
938	          if (dep_src2dst != nullptr) {
939	            (*dep_src2dst)[writer].push_back(block);
940	          }
941	          if (dep_dst2src != nullptr) {
942	            (*dep_dst2src)[block].push_back(writer);
943	          }
944	        }
945	      }
946	    }
947	    for (const BufferRegion &write : block->writes) {
948	      buffer_writers[write->buffer->data].push_back(block);
949	    }
950	  }
951	}
952	
953	class PipelineInjector : private StmtExprMutator {
954	public:
955	  static Stmt Inject(const PrimFunc &func) {
956	    auto global_symbol = func->GetAttr<String>(tvm::attr::kGlobalSymbol);
957	    PipelineInjector injector(global_symbol);
958	    for (const auto &kv : func->buffer_map) {
959	      const Buffer &buffer = kv.second;
960	      injector.buffer_data_to_buffer_.Set(buffer->data, buffer);
961	    }
962	    return injector(func->body);
963	  }
964	
965	private:
966	  explicit PipelineInjector(Optional<String> global_symbol)
967	      : global_symbol_(std::move(global_symbol)) {}
968	
969	  /*!
970	   * \brief Check the pipeline satisfies the following conditions:
971	   * 1. No conflicting order: The order of each statement should be unique.
972	   * 2. Reordering of statements doesn't break buffer access dependencies.
973	   * Specifically, for dependency (e.g. read-after-write) from statement A to
974	   * statement B, it requires: case 1: stage(A) < stage(B) case 2: stage(A) ==
975	   * stage(B) and order(A) < order(B)
976	   */
977	  void ValidatePipelineBody(const PipelineInfo &pipeline_info,
978	                            const Array<Block> &original_order) {
979	    std::unordered_set<int> used_orders;
980	    std::unordered_map<int, int> stage_max_order;
981	    std::unordered_map<int, const Block *> order_to_block;
982	    std::unordered_map<const Block *, int> block_to_stage;
983	    for (const Block &block : original_order) {
984	      const auto &stmt_info = pipeline_info.at(block);
985	      int order = stmt_info.order;
986	      CHECK(!used_orders.count(order))
987	          << "ValueError: Two statements in the software pipeline cannot have "
988	             "the same order";
989	      used_orders.insert(order);
990	    }
991	
992	    std::unordered_map<Block, Array<Block>, ObjectPtrHash, ObjectPtrEqual>
993	        dep_src2dst;
994	    BuildDependencyGraph(original_order, &dep_src2dst, nullptr);
995	
996	    for (const auto &pair : dep_src2dst) {
997	      const Block &src = pair.first;
998	      const auto &src_info = pipeline_info.at(src);
999	      const Array<Block> &dsts = pair.second;
1000	      for (const Block &dst : dsts) {
1001	        const auto &dst_info = pipeline_info.at(dst);
1002	        CHECK_LE(src_info.stage, dst_info.stage)
1003	            << "ValueError: statement " << dst << " in stage " << dst_info.stage
1004	            << " cannot depends on statement " << src << " in a later stage "
1005	            << src_info.stage;
1006	        if (src_info.stage == dst_info.stage) {
1007	          CHECK_LT(src_info.order, dst_info.order)
1008	              << "ValueError: two statements with buffer "
1009	                 "access dependency in the same stage of the "
1010	                 "software pipeline cannot be reordered";
1011	        }
1012	      }
1013	    }
1014	  }
1015	
1016	  Stmt VisitStmt_(const ForNode *op) final {
1017	    // Step 1: Recursively rewrite the children first.
1018	    For for_node = Downcast<For>(StmtExprMutator::VisitStmt_(op));
1019	    if (!HasPipelineAnnotation(op)) {
1020	      return for_node;
1021	    }
1022	    // Step 2: Find the body and buffer allocations of the pipeline. The body
1023	    // can be direct child of the for-loop. If the for-loop has BlockRealize as
1024	    // its child, the pipeline body will be the child of the block.
1025	    Stmt pipeline_body_root{nullptr};
1026	    bool pipeline_body_from_block = false;
1027	    Array<Buffer> pipeline_allocs;
1028	    Array<Buffer>
1029	        block_local_allocs; // buffers allocated in the pipeline block itself
1030	    if (const auto *realize = for_node->body.as<BlockRealizeNode>()) {
1031	      const auto &block = realize->block;
1032	      for (const auto &buffer : block->alloc_buffers) {
1033	        ICHECK(buffer->IsInstance<BufferNode>());
1034	        buffer_data_to_buffer_.Set(buffer->data, buffer);
1035	        allocated_buffers_.insert(buffer);
1036	      }
1037	      pipeline_body_root = block->body;
1038	      block_local_allocs = block->alloc_buffers;
1039	      pipeline_body_from_block = true;
1040	    } else {
1041	      pipeline_body_root = for_node->body;
1042	    }
1043	
1044	    const SeqStmtNode *pipeline_body_seq = nullptr;
1045	    std::vector<std::function<Stmt(Stmt)>> rewrap_fns;
1046	    std::vector<LetWrapper> loop_var_let_wrappers;
1047	    auto append_attr_wrapper = [&rewrap_fns](const AttrStmtNode *attr) {
1048	      Any node = attr->node;
1049	      String attr_key = attr->attr_key;
1050	      PrimExpr value = attr->value;
1051	      Span span = attr->span;
1052	      rewrap_fns.emplace_back(
1053	          [node = std::move(node), attr_key = std::move(attr_key),
1054	           value = std::move(value), span](Stmt body) -> Stmt {
1055	            return AttrStmt(node, attr_key, value, body, span);
1056	          });
1057	    };
1058	    {
1059	      Stmt current = pipeline_body_root;
1060	      while (true) {
1061	        if (const auto *seq_stmt = current.as<SeqStmtNode>()) {
1062	          pipeline_body_seq = seq_stmt;
1063	          break;
1064	        }
1065	        if (const auto *if_then_else = current.as<IfThenElseNode>()) {
1066	          ICHECK(!if_then_else->else_case.defined())
1067	              << "InjectSoftwarePipeline: Can't handle the body of the loop "
1068	                 "because the IfThenElse node has an else branch";
1069	          PrimExpr condition = if_then_else->condition;
1070	          Span span = if_then_else->span;
1071	          rewrap_fns.emplace_back(
1072	              [condition = std::move(condition), span](Stmt body) -> Stmt {
1073	                return IfThenElse(condition, body, Stmt(), span);
1074	              });
1075	          current = if_then_else->then_case;
1076	          continue;
1077	        }
1078	        if (const auto *let_stmt = current.as<LetStmtNode>()) {
1079	          // If this Let value uses the pipeline loop var, record it and push
1080	          // inside each rewritten block later so the loop var can be
1081	          // substituted with the correct per-iteration index. Otherwise, keep
1082	          // it as a normal wrapper.
1083	          bool uses_loop_var = UsesVar(
1084	              let_stmt->value,
1085	              [v = op->loop_var.get()](const VarNode *vn) { return vn == v; });
1086	          if (uses_loop_var) {
1087	            loop_var_let_wrappers.push_back({let_stmt->var, let_stmt->value});
1088	          } else {
1089	            Var var = let_stmt->var;
1090	            PrimExpr value = let_stmt->value;
1091	            Span span = let_stmt->span;
1092	            rewrap_fns.emplace_back([var = std::move(var),
1093	                                     value = std::move(value),
1094	                                     span](Stmt body) -> Stmt {
1095	              return LetStmt(var, value, body, span);
1096	            });
1097	          }
1098	          current = let_stmt->body;
1099	          continue;
1100	        }
1101	        if (const auto *attr = current.as<AttrStmtNode>()) {
1102	          append_attr_wrapper(attr);
1103	          current = attr->body;
1104	          continue;
1105	        }
1106	        LOG(FATAL) << "ValueError: The body of the software pipeline should be "
1107	                   << "SeqStmt, got " << current->GetTypeKey();
1108	      }
1109	    }
1110	    ICHECK(pipeline_body_seq != nullptr);
1111	
1112	    // Step 3: Blockize the components of the pipeline. Each child of the
1113	    // pipelined loop will be converted into a block.
1114	    PipelineInfo pipeline_info;
1115	    Array<Block> original_order; // pipeline body blocks in the original order
1116	
1117	    auto f_add_child = [&](const Stmt &child) {
1118	      original_order.push_back(MakeBlock(child, buffer_data_to_buffer_));
1119	    };
1120	    for (size_t i = 0; i < pipeline_body_seq->seq.size(); i++) {
1121	      const Stmt &child = pipeline_body_seq->seq[i];
1122	      const auto *nested_block_realize = child.as<BlockRealizeNode>();
1123	      if (nested_block_realize && is_one(nested_block_realize->predicate) &&
1124	          nested_block_realize->block->body->IsInstance<SeqStmtNode>()) {
1125	        const Block &nested_pipeline_block = nested_block_realize->block;
1126	        ICHECK(nested_pipeline_block->match_buffers
1127	                   .empty()); // match_buffer should have been lowered
1128	        for (const auto &buffer : nested_pipeline_block->alloc_buffers) {
1129	          buffer_data_to_buffer_.Set(buffer->data, buffer);
1130	          allocated_buffers_.insert(buffer);
1131	        }
1132	      }
1133	      f_add_child(child);
1134	    }
1135	
1136	    // Collect all buffers that are actually used in the pipeline loop body.
1137	    // This includes buffers allocated in outer blocks (like logits_smem) that
1138	    // are used inside the pipeline loop.
1139	    BufferUsageCollector collector(buffer_data_to_buffer_, allocated_buffers_);
1140	    pipeline_allocs = collector.Collect(SeqStmt(pipeline_body_seq->seq));
1141	
1142	    // Build a set of local allocs (buffers allocated in the pipeline block
1143	    // itself) for efficient lookup
1144	    std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual> local_allocs_set;
1145	    for (const auto &buffer : block_local_allocs) {
1146	      local_allocs_set.insert(buffer);
1147	    }
1148	    for (size_t i = 0; i < pipeline_body_seq->seq.size(); i++) {
1149	      const Stmt &child = pipeline_body_seq->seq[i];
1150	      const auto *nested_block_realize = child.as<BlockRealizeNode>();
1151	      if (nested_block_realize && is_one(nested_block_realize->predicate) &&
1152	          nested_block_realize->block->body->IsInstance<SeqStmtNode>()) {
1153	        for (const auto &buffer : nested_block_realize->block->alloc_buffers) {
1154	          local_allocs_set.insert(buffer);
1155	        }
1156	      }
1157	    }
1158	
1159	    // Check if any external buffer (from outer blocks) is already used in
1160	    // another pipeline. This would cause conflicts in multi-versioning.
1161	    for (const auto &buffer : pipeline_allocs) {
1162	      // Only check external buffers (not locally allocated in this pipeline)
1163	      if (local_allocs_set.count(buffer) == 0) {
1164	        CHECK(buffers_used_in_pipeline_.count(buffer) == 0)
1165	            << "Buffer '" << buffer->name
1166	            << "' is used in multiple software pipeline loops. "
1167	            << "This is not supported because multi-versioning would conflict.";
1168	        buffers_used_in_pipeline_.insert(buffer);
1169	      }
1170	    }
1171	
1172	    auto pipeline_stages = Downcast<Array<Integer>>(
1173	        op->annotations.at(tir::attr::software_pipeline_stage));
1174	    auto pipeline_orders = Downcast<Array<Integer>>(
1175	        op->annotations.at(tir::attr::software_pipeline_order));
1176	    CHECK_EQ(pipeline_stages.size(), original_order.size())
1177	        << "PrimFunc " << global_symbol_ << " has original order "
1178	        << original_order.Map(
1179	               [](const auto &block) { return block->name_hint; })
1180	        << ", but pipeline annotation is " << pipeline_stages
1181	        << " with different size";
1182	    CHECK_EQ(pipeline_orders.size(), original_order.size())
1183	        << "PrimFunc " << global_symbol_ << " has original order "
1184	        << original_order.Map(
1185	               [](const auto &block) { return block->name_hint; })
1186	        << ", but pipeline annotation is " << pipeline_orders
1187	        << " with different size";
1188	
1189	    std::unordered_set<int> pipeline_async_stages;
1190	    if (auto annot =
1191	            op->annotations.Get(tir::attr::software_pipeline_async_stages)) {
1192	      for (auto s : Downcast<Array<Integer>>(annot.value())) {
1193	        pipeline_async_stages.insert(s->value);
1194	      }
1195	    }
1196	
1197	    for (size_t i = 0; i < pipeline_stages.size(); i++) {
1198	      int stage = static_cast<int>(pipeline_stages[i]->value);
1199	      bool is_async =
1200	          pipeline_async_stages.find(stage) != pipeline_async_stages.end();
1201	      PipelineAnnotation stage_order{
1202	          stage,
1203	          /*order=*/static_cast<int>(pipeline_orders[i]->value), is_async,
1204	          /*original_idx=*/static_cast<int>(i)};
1205	      pipeline_info.emplace(original_order[i], stage_order);
1206	    }
1207	
1208	    ValidatePipelineBody(pipeline_info, original_order);
1209	
1210	    // Step 4: Rewrite the pipeline body.
1211	    // local_allocs contains buffers allocated in the pipeline block itself.
1212	    // pipeline_allocs contains all buffers that need multi-versioning,
1213	    // including buffers from outer blocks.
1214	    Array<Buffer> local_allocs = block_local_allocs;
1215	    // Add nested block allocs to local_allocs
1216	    for (size_t i = 0; i < pipeline_body_seq->seq.size(); i++) {
1217	      const Stmt &child = pipeline_body_seq->seq[i];
1218	      const auto *nested_block_realize = child.as<BlockRealizeNode>();
1219	      if (nested_block_realize && is_one(nested_block_realize->predicate) &&
1220	          nested_block_realize->block->body->IsInstance<SeqStmtNode>()) {
1221	        const Block &nested_pipeline_block = nested_block_realize->block;
1222	        for (const auto &buffer : nested_pipeline_block->alloc_buffers) {
1223	          local_allocs.push_back(buffer);
1224	        }
1225	      }
1226	    }
1227	
1228	    PipelineRewriter rewriter(buffer_data_to_buffer_, pipeline_allocs,
1229	                              local_allocs, tvm::ffi::GetRef<For>(op),
1230	                              pipeline_info, loop_var_let_wrappers);
1231	    Stmt pipeline = rewriter.BuildPipeline();
1232	
1233	    // Store the buffer remapping for updating outer block alloc_buffers
1234	    for (const auto &kv : rewriter.GetBufferRemap()) {
1235	      pending_buffer_remap_.Set(kv.first, kv.second);
1236	    }
1237	    auto apply_wrappers = [&](Stmt stmt) {
1238	      for (auto it = rewrap_fns.rbegin(); it != rewrap_fns.rend(); ++it) {
1239	        stmt = (*it)(stmt);
1240	      }
1241	      return stmt;
1242	    };
1243	    if (!rewrap_fns.empty()) {
1244	      if (pipeline_body_from_block) {
1245	        BlockRealize pipeline_realize = Downcast<BlockRealize>(pipeline);
1246	        Block pipeline_block = pipeline_realize->block;
1247	        {
1248	          BlockNode *block_node = pipeline_block.CopyOnWrite();
1249	          block_node->body = apply_wrappers(block_node->body);
1250	        }
1251	        pipeline = BlockRealize(pipeline_realize->iter_values,
1252	                                pipeline_realize->predicate, pipeline_block,
1253	                                pipeline_realize->span);
1254	      } else {
1255	        pipeline = apply_wrappers(pipeline);
1256	      }
1257	    }
1258	
1259	    if (const auto *realize = op->body.as<BlockRealizeNode>()) {
1260	      const auto &block = realize->block;
1261	      for (const auto &buffer : block->alloc_buffers) {
1262	        buffer_data_to_buffer_.erase(buffer->data);
1263	        allocated_buffers_.erase(buffer);
1264	      }
1265	    }
1266	    return pipeline;
1267	  }
1268	
1269	  Stmt VisitStmt_(const BlockNode *op) final {
1270	    for (const auto &buffer : op->alloc_buffers) {
1271	      buffer_data_to_buffer_.Set(buffer->data, buffer);
1272	      allocated_buffers_.insert(buffer);
1273	    }
1274	
1275	    Block block = Downcast<Block>(StmtExprMutator::VisitStmt_(op));
1276	
1277	    // Update alloc_buffers with any pending buffer remaps from pipeline
1278	    // rewriting. This handles buffers allocated in this block but
1279	    // multi-versioned during pipeline rewriting of inner loops.
1280	    Array<Buffer> new_alloc_buffers;
1281	    for (const auto &buffer : block->alloc_buffers) {
1282	      if (auto remapped = pending_buffer_remap_.Get(buffer)) {
1283	        new_alloc_buffers.push_back(remapped.value());
1284	        // Remove from pending after applying
1285	        pending_buffer_remap_.erase(buffer);
1286	      } else {
1287	        new_alloc_buffers.push_back(buffer);
1288	      }
1289	    }
1290	
1291	    Array<Array<BufferRegion>> access =
1292	        GetBlockReadWriteRegion(block, buffer_data_to_buffer_);
1293	    BlockNode *n = block.CopyOnWrite();
1294	    n->reads = access[0];
1295	    n->writes = access[1];
1296	    n->alloc_buffers = std::move(new_alloc_buffers);
1297	
1298	    for (const auto &buffer : op->alloc_buffers) {
1299	      buffer_data_to_buffer_.erase(buffer->data);
1300	      allocated_buffers_.erase(buffer);
1301	    }
1302	    return block;
1303	  }
1304	
1305	  bool HasPipelineAnnotation(const ForNode *op) const {
1306	    auto it1 = op->annotations.find(tir::attr::software_pipeline_stage);
1307	    auto it2 = op->annotations.find(tir::attr::software_pipeline_order);
1308	    bool has_stage = it1 != op->annotations.end();
1309	    bool has_order = it2 != op->annotations.end();
1310	    if (has_stage && has_order) {
1311	      return true;
1312	    }
1313	    if (has_stage) {
1314	      LOG(FATAL)
1315	          << "ValueError: Stage of the software pipeline is not defined.";
1316	    }
1317	    if (has_order) {
1318	      LOG(FATAL)
1319	          << "ValueError: Order of the software pipeline is not defined.";
1320	    }
1321	    return false;
1322	  }
1323	
1324	  Map<Var, Buffer> buffer_data_to_buffer_;
1325	  std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual> allocated_buffers_;
1326	  Map<Buffer, Buffer> pending_buffer_remap_;
1327	  // Buffers from outer blocks that have been used in a pipeline loop.
1328	  // Used to detect if the same buffer is used in multiple pipeline loops.
1329	  std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual>
1330	      buffers_used_in_pipeline_;
1331	  Optional<String> global_symbol_;
1332	};
1333	} // namespace software_pipeline
1334	
1335	/*!
1336	 * \brief Transform annotated loops into pipelined one that parallelize
1337	 * producers and consumers. \return The IR transform pass.
1338	 */
1339	tir::transform::Pass InjectSoftwarePipeline() {
1340	  using namespace tir::transform;
1341	  auto pass_func = [=](PrimFunc f, const IRModule &m, const PassContext &ctx) {
1342	    auto *fptr = f.CopyOnWrite();
1343	    fptr->body = software_pipeline::PipelineInjector::Inject(f);
1344	    fptr->body = ConvertSSA(std::move(fptr->body));
1345	    return f;
1346	  };
1347	  return CreatePrimFuncPass(pass_func, 0, "tl.InjectSoftwarePipeline", {});
1348	}
1349	
1350	TVM_FFI_STATIC_INIT_BLOCK() {
1351	  namespace refl = tvm::ffi::reflection;
1352	  refl::GlobalDef().def("tl.transform.InjectSoftwarePipeline",
1353	                        InjectSoftwarePipeline);
1354	}
1355	
1356	} // namespace tl
1357	} // namespace tvm
