42	
43	namespace tvm {
44	namespace tl {
45	
46	using namespace tir;
47	using namespace tir::transform;
48	using arith::IRMutatorWithAnalyzer;
49	using arith::IRVisitorWithAnalyzer;
50	
51	class TmaTraitsCollector : public StmtExprVisitor {
52	public:
53	  TmaTraitsCollector() { Initialize(); }
54	
55	  void Initialize() {
56	    bulk_copy_bytes = 0;
57	    loop_extents = 1;
58	  }
59	
60	  void Collect(const Stmt &stmt) { VisitStmt(stmt); }
61	
62	  PrimExpr BulkCopyBytes() { return bulk_copy_bytes; }
63	
64	private:
65	  void VisitExpr_(const CallNode *call) final {
66	    if (call->op.same_as(tma_load()) || call->op.same_as(tma_load_im2col())) {
67	      auto arg0 = call->args[0].as<Call>();
68	      if (call->op.same_as(tma_load()) && arg0 &&
69	          !arg0.value()->op.same_as(create_tma_descriptor())) {
70	        // 1D TMA load has tvm_access_ptr of shared tensor in its args[0]
71	        bulk_copy_bytes = call->args[3] * loop_extents;
72	      } else {
73	        Call access_ptr = Downcast<Call>(call->args[2]);
74	        ICHECK(access_ptr->op.same_as(builtin::tvm_access_ptr()));
75	        int type_bytes = access_ptr->args[0]->dtype.bytes();
76	        bulk_copy_bytes += access_ptr->args[3] * loop_extents * type_bytes;
77	      }
78	    }
79	    StmtExprVisitor::VisitExpr_(call);
80	  }
81	
82	  void VisitStmt_(const ForNode *op) final {
83	    PrimExpr old_loop_evtents = loop_extents;
84	    loop_extents *= op->extent;
85	    StmtExprVisitor::VisitStmt_(op);
86	    loop_extents = old_loop_evtents;
87	  }
88	
89	  PrimExpr bulk_copy_bytes = 0;
90	  PrimExpr loop_extents = 1;
91	};
92	
93	class TmaExpectTxRewriter : public IRMutatorWithAnalyzer {
94	public:
95	  static PrimFunc Rewrite(PrimFunc f, arith::Analyzer *analyzer) {
96	    TmaExpectTxRewriter rewriter(analyzer);
97	    f.CopyOnWrite()->body = rewriter(f->body);
98	    return f;
99	  }
100	
101	private:
102	  bool inside_tma_block_{false};
103	  bool visited_tma_load_{false};
104	  IterVar thread_var_ = IterVar(Range::FromMinExtent(0, 1), Var("v_thread"),
105	                                IterVarType::kDataPar);
106	
107	  PrimExpr makeGetBarrier(PrimExpr barrier_id) {
108	    return Call(DataType::Handle(), get_mbarrier(), {std::move(barrier_id)});
109	  }
110	
111	  Stmt makeExpectTX(PrimExpr barrier_id, PrimExpr bytes) {
112	    auto call = Call(DataType::Handle(), mbarrier_expect_tx(),
113	                     {makeGetBarrier(std::move(barrier_id)), std::move(bytes)});
114	    return Evaluate(call);
115	  }
116	
117	  TmaExpectTxRewriter(arith::Analyzer *analyzer)
118	      : IRMutatorWithAnalyzer(analyzer) {}
119	
120	  Stmt VisitStmt_(const AttrStmtNode *op) final {
121	
122	    if (op->attr_key == tir::attr::thread_extent) {
123	      IterVar iv = Downcast<IterVar>(op->node);
124	      if (iv->thread_tag == "threadIdx.x") {
125	        ICHECK(iv->dom->extent.as<IntImmNode>());
126	        thread_var_ = iv;
127	      }
128	    }
129	    return IRMutatorWithAnalyzer::VisitStmt_(op);
130	  }
131	
132	  Stmt VisitStmt_(const IfThenElseNode *op) {
133	    // Check if this is the TMA block
134	    bool flag = false;
135	    if (op->condition.as<CallNode>()) {
136	      flag = op->condition.as<CallNode>()->op.same_as(tl_shuffle_elect());
137	    }
138	    if (op->condition.as<EQNode>() || flag) {
139	      Stmt ret = IRMutatorWithAnalyzer::VisitStmt_(op);
140	
141	      if (visited_tma_load_) {
142	        auto then_case = op->then_case;
143	        TmaTraitsCollector collector;
144	        collector.Collect(then_case);
145	
146	        Array<Stmt> stmts;
147	        if (!is_zero(collector.BulkCopyBytes())) {
148	          auto expect_tx = makeExpectTX(0, collector.BulkCopyBytes());
149	          stmts.push_back(expect_tx);
150	        }
151	        stmts.push_back(then_case);
152	        if (stmts.size() == 1) {
153	          return IfThenElse(op->condition, stmts[0], op->else_case);
154	        } else {
155	          auto seq_stmt = SeqStmt(stmts);
156	          return IfThenElse(op->condition, seq_stmt, op->else_case);
157	        }
158	      }
159	      visited_tma_load_ = false;
160	      return ret;
161	    }
162	    return IRMutatorWithAnalyzer::VisitStmt_(op);
163	  }
164	
165	  PrimExpr VisitExpr_(const CallNode *op) {
166	    if (op->op.same_as(tma_load()) || op->op.same_as(tma_load_im2col())) {
167	      auto arg0 = op->args[0].as<Call>();
168	      bool is_1d_tma_load =
169	          arg0 && !arg0.value()->op.same_as(create_tma_descriptor()) &&
170	          op->op.same_as(tma_load());
171	      visited_tma_load_ = true;
172	      Array<PrimExpr> new_args = op->args;
173	      new_args.Set(is_1d_tma_load ? 2 : 1,
174	                   Call(DataType::Handle(), get_mbarrier(),
175	                        {IntImm(DataType::Int(32), 0)}));
176	      return Call(op->dtype, op->op, new_args);
177	    }
178	    return IRMutatorWithAnalyzer::VisitExpr_(op);
179	  }
180	};
181	
182	class TmaBarrierCollector : public IRVisitorWithAnalyzer {
183	public:
184	  TmaBarrierCollector(Map<Var, Buffer> buffer_data_to_buffer)
185	      : buffer_data_to_buffer_(std::move(buffer_data_to_buffer)) {}
186	
187	  Map<ObjectRef, PrimExpr> tma_op_to_barrier_id() {
188	    return tma_op_to_barrier_id_;
189	  }
190	  Map<PrimExpr, IntImm> barrier_id_to_range() { return barrier_id_to_range_; }
191	
192	private:
193	  void UpdateBarrierRange(const PrimExpr &barrier_id, const IntImm &extent) {
194	    if (barrier_id_to_range_.count(barrier_id)) {
195	      auto old_extent = barrier_id_to_range_[barrier_id];
196	      ICHECK_EQ(old_extent->value, extent->value)
197	          << "barrier_id: " << barrier_id << " has different extent";
198	      barrier_id_to_range_.Set(barrier_id, extent);
199	    } else {
200	      barrier_id_to_range_.Set(barrier_id, extent);
201	    }
202	  }
203	
204	  void VisitStmt_(const EvaluateNode *op) final {
205	    if (const auto *call = op->value.as<CallNode>()) {
206	      if (call->op.same_as(tma_load()) || call->op.same_as(tma_load_im2col())) {
207	        pending_tma_ops_.push_back(tvm::ffi::GetRef<Call>(call));
208	      } else if (call->op.same_as(mbarrier_expect_tx())) {
209	        pending_tma_ops_.push_back(tvm::ffi::GetRef<Call>(call));
210	      } else if (call->op.same_as(builtin::ptx_arrive_barrier())) {
211	        PrimExpr barrier_id = call->args[0];
212	        for (const auto &tma_call : pending_tma_ops_) {
213	          tma_op_to_barrier_id_.Set(tma_call, barrier_id);
214	        }
215	        auto const_int_bound = analyzer_.const_int_bound(thread_var_);
216	        auto extent =
217	            const_int_bound->max_value - const_int_bound->min_value + 1;
218	        UpdateBarrierRange(barrier_id, IntImm(DataType::Int(32), extent));
219	        pending_tma_ops_.clear();
220	      } else if (call->op.same_as(builtin::ptx_wait_barrier())) {
221	        PrimExpr barrier_id = call->args[0];
222	        auto const_int_bound = analyzer_.const_int_bound(thread_var_);
223	        auto extent =
224	            const_int_bound->max_value - const_int_bound->min_value + 1;
225	        UpdateBarrierRange(barrier_id, IntImm(DataType::Int(32), extent));
226	      }
227	    }
228	    StmtExprVisitor::VisitStmt_(op);
229	  }
230	
231	  void VisitStmt_(const AttrStmtNode *op) {
232	    if (op->attr_key == tir::attr::thread_extent) {
233	      IterVar iv = Downcast<IterVar>(op->node);
234	      if (iv->thread_tag == "threadIdx.x") {
235	        thread_var_ = iv;
236	      }
237	    }
238	    IRVisitorWithAnalyzer::VisitStmt_(op);
239	  }
240	
241	  IterVar thread_var_;
242	  std::vector<Call> pending_tma_ops_;
243	  Map<ObjectRef, PrimExpr> tma_op_to_barrier_id_;
244	  Map<PrimExpr, IntImm> barrier_id_to_range_;
245	  Map<Var, Buffer> buffer_data_to_buffer_;
246	};
247	
248	class TmaSequenceCollector : public IRVisitorWithAnalyzer {
249	public:
250	  TmaSequenceCollector(Map<ObjectRef, PrimExpr> tma_op_to_barrier_id)
251	      : tma_op_to_barrier_id_(std::move(tma_op_to_barrier_id)) {}
252	
253	  std::vector<bool> GetSequence() {
254	    std::vector<bool> clear_zero_list(expect_tx_count_, false);
255	    int zero_idx = -1;
256	    int zero_count = 0;
257	
258	    for (auto v : sequence) {
259	      if (v == 0) {
260	        zero_count += 1;
261	        zero_idx += 1;
262	      } else {
263	        if (zero_count == 1) {
264	          clear_zero_list[zero_idx] = expect_[zero_idx] && !has_simt_copy_;
265	          if (clear_zero_list[zero_idx] == false) {
266	            int begin = int_sets_[zero_idx].min().as<IntImmNode>()->value;
267	            int end = int_sets_[zero_idx].max().as<IntImmNode>()->value;
268	            for (int i = begin; i <= end; ++i) {
269	              restore_barrier_ids_.push_back(i);
270	            }
271	          }
272	        } else {
273	          for (int i{zero_idx}; i > zero_idx - zero_count; --i) {
274	            int begin = int_sets_[i].min().as<IntImmNode>()->value;
275	            int end = int_sets_[i].max().as<IntImmNode>()->value;
276	            for (int i = begin; i <= end; ++i) {
277	              restore_barrier_ids_.push_back(i);
278	            }
279	          }
280	        }
281	        zero_count = 0;
282	      }
283	    }
284	
285	    return clear_zero_list;
286	  }
287	
288	  std::vector<int> GetRestoreBarrierIds() { return restore_barrier_ids_; }
289	
290	  void VisitStmt_(const ForNode *op) final {
291	    var_int_set_.Set(op->loop_var,
292	                     arith::IntSet::FromMinExtent(op->min, op->extent));
293	    IRVisitorWithAnalyzer::VisitStmt_(op);
294	  }
295	
296	  void VisitExpr_(const CallNode *op) final {
297	    if (op->op.same_as(mbarrier_expect_tx())) {
298	      auto call_ref = tvm::ffi::GetRef<Call>(op);
299	      if (tma_op_to_barrier_id_.count(call_ref)) {
300	        PrimExpr e = tma_op_to_barrier_id_[call_ref].as<CallNode>()->args[0];
301	        auto int_set = arith::EvalSet(e, var_int_set_);
302	        expect_.push_back(if_depth_ == 1);
303	        sequence.push_back(0);
304	        int_sets_.push_back(int_set);
305	        expect_tx_count_ += 1;
306	      }
307	    } else if (op->op.same_as(builtin::ptx_arrive_barrier())) {
308	      sequence.push_back(1);
309	    } else if (op->op.same_as(builtin::ptx_cp_async_barrier())) {
310	      has_simt_copy_ = true;
311	    }
312	    IRVisitorWithAnalyzer::VisitExpr_(op);
313	  }
314	
315	  void VisitStmt_(const IfThenElseNode *op) final {
316	    if_depth_ += 1;
317	
318	    IRVisitorWithAnalyzer::VisitStmt(op->then_case);
319	
320	    if (op->else_case) {
321	      IRVisitorWithAnalyzer::VisitStmt(op->else_case.value());
322	    }
323	    if_depth_ -= 1;
324	  }
325	
326	  std::vector<int> sequence;
327	  int expect_tx_count_{0};
328	  std::vector<bool> expect_;
329	  bool has_simt_copy_{false};
330	  std::vector<int> restore_barrier_ids_;
331	  int if_depth_{0};
332	  Map<ObjectRef, PrimExpr> tma_op_to_barrier_id_;
333	  arith::Analyzer *analyzer_{};
334	  Map<Var, arith::IntSet> var_int_set_;
335	  std::vector<arith::IntSet> int_sets_;
336	};
337	
338	class BarrierCreationRewriter : public StmtExprMutator {
339	public:
340	  BarrierCreationRewriter(std::vector<int> restore_barrier_ids,
341	                          PrimExpr producer_thread_extent,
342	                          int ensure_min_count = 0,
343	                          PrimExpr default_barrier_thread_count = 1)
344	      : restore_barrier_ids_(std::move(restore_barrier_ids)),
345	        producer_thread_extent_(std::move(producer_thread_extent)),
346	        ensure_min_count_(ensure_min_count),
347	        default_barrier_thread_count_(std::move(default_barrier_thread_count)) {
348	  }
349	
350	  PrimExpr VisitExpr_(const CallNode *op) {
351	    if (op->op.same_as(create_list_of_mbarrier())) {
352	      size_t cur_n = op->args.size();
353	      size_t need_n =
354	          std::max<size_t>(cur_n, static_cast<size_t>(ensure_min_count_));
355	
356	      // Mark barriers to restore across the full needed length, not just the
357	      // original length, so newly appended entries can be restored as well.
358	      std::vector<bool> replace(need_n, false);
359	      for (auto &id : restore_barrier_ids_) {
360	        if (id >= 0 && static_cast<size_t>(id) < replace.size()) {
361	          replace[id] = true;
362	        }
363	      }
364	
365	      Array<PrimExpr> new_args;
366	      new_args.reserve(need_n);
367	
368	      // Preserve/override existing entries
369	      for (size_t i{0}; i < cur_n; ++i) {
370	        if (replace[i]) {
371	          new_args.push_back(producer_thread_extent_);
372	        } else {
373	          new_args.push_back(op->args[i]);
374	        }
375	      }
376	      // Append additional barriers if required
377	      for (size_t i = cur_n; i < need_n; ++i) {
378	        if (replace[i]) {
379	          new_args.push_back(producer_thread_extent_);
380	        } else {
381	          new_args.push_back(default_barrier_thread_count_);
382	        }
383	      }
384	
385	      return Call(op->dtype, op->op, new_args);
386	    } else {
387	      return StmtExprMutator::VisitExpr_(op);
388	    }
389	  }
390	
391	private:
392	  std::vector<int> restore_barrier_ids_;
393	  PrimExpr producer_thread_extent_;
394	  int ensure_min_count_{0};
395	  PrimExpr default_barrier_thread_count_{1};
396	};
397	
398	// we trust mbarrier_wait_parity to be correct
399	class TmaBarrierRewriter : public IRMutatorWithAnalyzer {
400	public:
401	  TmaBarrierRewriter(arith::Analyzer *analyzer,
402	                     Map<ObjectRef, PrimExpr> tma_op_to_barrier_id,
403	                     Map<PrimExpr, IntImm> barrier_id_to_range,
404	                     bool has_create_list_of_mbarrier)
405	      : IRMutatorWithAnalyzer(analyzer),
406	        tma_op_to_barrier_id_(std::move(tma_op_to_barrier_id)),
407	        barrier_id_to_range_(std::move(barrier_id_to_range)),
408	        has_create_list_of_mbarrier_(has_create_list_of_mbarrier) {}
409	
410	  static PrimFunc Rewrite(PrimFunc f, arith::Analyzer *analyzer) {
411	    auto buffer_lca = DetectBufferAccessLCA(f);
412	    Map<Var, Buffer> buffer_data_to_buffer_;
413	    for (auto [buffer, _] : buffer_lca)
414	      buffer_data_to_buffer_.Set(buffer->data, buffer);
415	    f = TmaExpectTxRewriter::Rewrite(f, analyzer);
416	    TmaBarrierCollector collector(buffer_data_to_buffer_);
417	    collector(f->body);
418	    bool has_create_list_of_mbarrier = false;
419	    PostOrderVisit(f->body, [&](const ObjectRef &node) {
420	      if (const auto *call = node.as<CallNode>()) {
421	        if (call->op.same_as(create_list_of_mbarrier())) {
422	          has_create_list_of_mbarrier = true;
423	        } else if (call->op.same_as(builtin::ptx_init_barrier_thread_count())) {
424	          has_create_list_of_mbarrier = true;
425	        }
426	      }
427	    });
428	    TmaBarrierRewriter rewriter(analyzer, collector.tma_op_to_barrier_id(),
429	                                collector.barrier_id_to_range(),
430	                                has_create_list_of_mbarrier);
431	    f.CopyOnWrite()->body = rewriter(f->body);
432	    // Compute the minimum number of barriers actually referenced in the body
433	    // after TMA barrier rewrites (e.g., get_mbarrier(0) inserted for TMA).
434	    struct GetMbarrierMaxIdxCollector : public StmtExprVisitor {
435	      int max_idx{-1};
436	      void VisitExpr_(const CallNode *op) final {
437	        if (op->op.same_as(get_mbarrier())) {
438	          if (op->args.size() == 1) {
439	            if (const auto *imm = op->args[0].as<IntImmNode>()) {
440	              max_idx = std::max(max_idx, static_cast<int>(imm->value));
441	            }
442	          }
443	        }
444	        StmtExprVisitor::VisitExpr_(op);
445	      }
446	    };
447	
448	    GetMbarrierMaxIdxCollector max_idx_collector;
449	    max_idx_collector(f->body);
450	    int ensure_min_count = max_idx_collector.max_idx + 1; // 0-based -> count
451	
452	    // For simple TMA-only producers, default barrier arrive count should be 1
453	    // (only the elected leader performs the TMA arrive/expect).
454	    auto barrier_creation_rewriter = BarrierCreationRewriter(
455	        rewriter.restore_barrier_ids_, rewriter.producer_thread_extent_,
456	        ensure_min_count, Integer(1));
457	    f.CopyOnWrite()->body = barrier_creation_rewriter(f->body);
458	    return f;
459	  }
460	
461	private:
462	  Stmt VisitStmt_(const BlockNode *op) {
463	    auto block = tvm::ffi::GetRef<Block>(op);
464	    if (!has_create_list_of_mbarrier_ && !barrier_id_to_range_.empty() &&
465	        op->name_hint == MainBlockName) {
466	      ICHECK(false) << "Please declare create_list_of_mbarrier.";
467	    }
468	    return IRMutatorWithAnalyzer::VisitStmt_(op);
469	  }
470	
471	  Stmt VisitStmt_(const IfThenElseNode *op) {
472	    if (first_if) {
473	      if (op->condition.as<GENode>()) {
474	        producer_thread_extent_ =
475	            thread_var_->dom->extent - op->condition.as<GENode>()->b;
476	      }
477	      TmaSequenceCollector collector(tma_op_to_barrier_id_);
478	      collector(op->then_case);
479	      clear_expect_list_ = collector.GetSequence();
480	      restore_barrier_ids_ = collector.GetRestoreBarrierIds();
481	      first_if = false;
482	
483	      is_producer_ = true;
484	
485	      auto then_case = StmtExprMutator::VisitStmt(op->then_case);
486	
487	      is_producer_ = false;
488	      Stmt else_case;
489	      if (op->else_case.defined())
490	        else_case = StmtExprMutator::VisitStmt(op->else_case.value());
491	      return IfThenElse(op->condition, then_case, else_case);
492	    }
493	    return StmtExprMutator::VisitStmt_(op);
494	  }
495	
496	  Stmt VisitStmt_(const AttrStmtNode *op) final {
497	    if (op->attr_key == "kWarpSpecializationScope") {
498	      has_warp_specialization_ = true;
499	      first_if = true;
500	    } else if (op->attr_key == tir::attr::thread_extent &&
501	               Downcast<IterVar>(op->node)->thread_tag == "threadIdx.x") {
502	      thread_var_ = Downcast<IterVar>(op->node);
503	    }
504	    return IRMutatorWithAnalyzer::VisitStmt_(op);
505	  }
506	
507	  PrimExpr VisitExpr_(const CallNode *op) {
508	    if (op->op.same_as(tma_load()) || op->op.same_as(tma_load_im2col())) {
509	      auto call_ref = tvm::ffi::GetRef<Call>(op);
510	      if (!tma_op_to_barrier_id_.count(call_ref)) {
511	        // For 1D TMA loads, promote raw integer barrier id to get_mbarrier(id)
512	        // so codegen can emit mbarrier[index]. This handles degenerate
513	        // producer-only kernels where no arrive() is seen and mapping is empty.
514	        auto arg0 = op->args[0].as<Call>();
515	        bool is_1d_tma_load =
516	            arg0 && !arg0.value()->op.same_as(create_tma_descriptor()) &&
517	            !arg0.value()->op.same_as(create_tma_im2col_descriptor());
518	        if (is_1d_tma_load && op->args.size() >= 3) {
519	          if (const auto *imm = op->args[2].as<IntImmNode>()) {
520	            Array<PrimExpr> new_args = op->args;
521	            new_args.Set(2, Call(DataType::Handle(), get_mbarrier(),
522	                                 {IntImm(DataType::Int(32),
523	                                         static_cast<int>(imm->value))}));
524	            return Call(op->dtype, op->op, new_args);
525	          }
526	        }
527	        return IRMutatorWithAnalyzer::VisitExpr_(op);
528	      }
529	      auto barrier_id = tma_op_to_barrier_id_[call_ref];
530	      auto new_args = op->args;
531	      auto arg0 = op->args[0].as<Call>();
532	      auto is_1d_tma_load =
533	          arg0 && !arg0.value()->op.same_as(create_tma_descriptor()) &&
534	          !arg0.value()->op.same_as(create_tma_im2col_descriptor());
535	      if (is_1d_tma_load) {
536	        new_args.Set(2, barrier_id);
537	      } else {
538	        new_args.Set(1, barrier_id);
539	      }
540	      return Call(op->dtype, op->op, new_args);
541	    } else if (op->op.same_as(mbarrier_expect_tx())) {
542	      auto call_ref = tvm::ffi::GetRef<Call>(op);
543	      if (!tma_op_to_barrier_id_.count(call_ref)) {
544	        return IRMutatorWithAnalyzer::VisitExpr_(op);
545	      }
546	      auto barrier_id = tma_op_to_barrier_id_[call_ref];
547	      auto new_args = op->args;
548	      new_args.Set(0, barrier_id);
549	      if (!has_warp_specialization_)
550	        clear_arrive_ = false;
551	      else
552	        clear_arrive_ = clear_expect_list_[cur_expect_idx_++];
553	      if (clear_arrive_) {
554	        return Call(op->dtype, builtin::ptx_arrive_barrier_expect_tx(),
555	                    new_args);
556	      }
557	      return Call(op->dtype, op->op, new_args);
558	    } else if (op->op.same_as(builtin::ptx_arrive_barrier())) {
559	      if (clear_arrive_) {
560	        clear_arrive_ = false;
561	        return 0;
562	      }
563	      // by default, all threads must wait.
564	      auto new_args = op->args;
565	      return Call(op->dtype, op->op, new_args);
566	    }
567	    return IRMutatorWithAnalyzer::VisitExpr_(op);
568	  }
569	  Map<ObjectRef, PrimExpr> tma_op_to_barrier_id_;
570	  Map<PrimExpr, IntImm> barrier_id_to_range_;
571	  bool has_create_list_of_mbarrier_;
572	  bool clear_arrive_{false};
573	  bool first_if{false}, has_warp_specialization_{false}, is_producer_{false};
574	  IterVar thread_var_;
575	  int tma_expect_tx_{0}, cur_expect_idx_{0};
576	  std::vector<bool> clear_expect_list_;
577	  std::vector<int> restore_barrier_ids_;
578	  PrimExpr producer_thread_extent_;
579	};
580	
581	tvm::transform::Pass InjectTmaBarrier() {
582	  auto pass_func = [=](PrimFunc f, const IRModule &m, const PassContext &ctx) {
583	    // Check if function only uses threadIdx.x before proceeding
584	    if (!ThreadTagChecker::HasOnlyThreadIdxX(f)) {
585	      LOG(WARNING) << "InjectTmaBarrier will be disabled because the program "
586	                      "uses thread tags other than threadIdx.x\n"
587	                   << "If you want to use TMA barrier, please refactor "
588	                      "your program to use threadIdx.x only";
589	      // Return original function unchanged if other thread tags are found
590	      return f;
591	    }
592	    arith::Analyzer analyzer;
593	    return TmaBarrierRewriter::Rewrite(f, &analyzer);
594	  };
595	  return CreatePrimFuncPass(pass_func, 0, "tl.InjectTmaBarrier", {});
596	}
597	
598	TVM_FFI_STATIC_INIT_BLOCK() {
599	  namespace refl = tvm::ffi::reflection;
600	  refl::GlobalDef().def("tl.transform.InjectTmaBarrier", InjectTmaBarrier);
601	}
602	
